const $ = s => document.querySelector(s);
const EMPTY_DATA = () => ({income:[],expenses:[],loans:[],emi:[],people:[],ledger:[],career:[],settings:{budgets:{},categories:["Food & Dining","Mobile & Internet","Shopping","Travel","Bills & Utilities","Health","Education","Entertainment","Salary","Freelance","Bonus","Other"]}});
function readSession(){try{const raw=localStorage.getItem("abs_user");if(raw)return JSON.parse(raw)}catch(e){};try{const m=document.cookie.match(/(?:^|; )abs_session=([^;]+)/);if(m)return JSON.parse(decodeURIComponent(m[1]))}catch(e){};return null}
function persistSession(user){localStorage.setItem("abs_user",JSON.stringify(user));document.cookie="abs_session="+encodeURIComponent(JSON.stringify(user))+"; path=/; max-age=31536000; SameSite=Lax"}
function clearSession(){localStorage.removeItem("abs_user");document.cookie="abs_session=; path=/; max-age=0; SameSite=Lax"}
const state = {user:readSession(),tab:"dashboard",theme:localStorage.getItem("abs_theme")||"dark",data:null,admin:false};

// Initialize Firebase once the Firebase compat scripts and config from index.html are available.
(function initABSFirebase(){
  try{
    if(typeof firebase === "undefined" || !window.ABS_FIREBASE_CONFIG) return;
    if(!firebase.apps || !firebase.apps.length) firebase.initializeApp(window.ABS_FIREBASE_CONFIG);
  }catch(err){
    console.error("ABS Firebase initialization failed",err);
  }
})();
const ABS_ADMIN_EMAIL="shkadmin@absdashboard.app";
const ABS_ADMIN_UID="e38F5FVubhbEmCNAPorz0D5GODG2";
function firebaseAdminReady(){return typeof firebase!=="undefined"&&firebase.apps&&firebase.apps.length&&firebase.auth&&firebase.firestore}
async function firebaseAdminLogin(password){
  if(!firebaseAdminReady()) throw new Error("Firebase is not loaded. Please refresh the app.");
  const cred=await firebase.auth().signInWithEmailAndPassword(ABS_ADMIN_EMAIL,password);
  if(cred.user.uid!==ABS_ADMIN_UID){await firebase.auth().signOut();throw new Error("Administrator authorization failed.");}
  const snap=await firebase.firestore().collection("admins").doc(cred.user.uid).get();
  if(!snap.exists || snap.data()?.role!=="admin"){await firebase.auth().signOut();throw new Error("Administrator authorization failed.");}
  return cred.user;
}
async function restoreFirebaseAdminSession(){
  if(!firebaseAdminReady()) return false;
  const u=firebase.auth().currentUser;
  if(!u || u.uid!==ABS_ADMIN_UID) return false;
  try{
    const snap=await firebase.firestore().collection("admins").doc(u.uid).get();
    if(!snap.exists || snap.data()?.role!=="admin"){await firebase.auth().signOut();return false;}
    state.admin=true;
    openAdminPanel();
    return true;
  }catch(e){console.error("ABS admin session restore failed",e);return false;}
}
function dataKey(){return state.user?.mobile?`abs_data_${state.user.mobile}`:"abs_data"}
function ensureData(){state.data=JSON.parse(localStorage.getItem(dataKey())||"null")||EMPTY_DATA();if(!state.data.settings)state.data.settings={};if(!Array.isArray(state.data.settings.categories))state.data.settings.categories=EMPTY_DATA().settings.categories.slice();if(!Array.isArray(state.data.settings.incomeCategories))state.data.settings.incomeCategories=["Salary","Freelance","Business","Bonus","Interest","Gift","Other"];if(!Array.isArray(state.data.settings.customCategories))state.data.settings.customCategories=[];return state.data}
if(state.user){ensureData();} else {state.data=EMPTY_DATA();}
state.data.settings=state.data.settings||EMPTY_DATA().settings; state.data.settings.categories=state.data.settings.categories||EMPTY_DATA().settings.categories; state.data.people=state.data.people||[]; state.data.ledger=state.data.ledger||[];
const money=n=>"₹"+Number(n||0).toLocaleString("en-IN",{maximumFractionDigits:0});
const save=()=>{if(!state.user?.mobile)return;localStorage.setItem(dataKey(),JSON.stringify(state.data));syncUserRegistry();};
function userRegistry(){return JSON.parse(localStorage.getItem("abs_users")||"[]")}
function nextAbsSerial(users){const nums=users.map(u=>String(u.absId||"").match(/(\d{4,})$/)).filter(Boolean).map(m=>Number(m[1])).filter(n=>Number.isFinite(n));return Math.max(1000,...nums)+1}
function makeAbsId(mobile,serial){return `ABS${String(mobile||"").slice(-2)}${serial}`}
function ensureAbsIds(){const users=userRegistry();let serial=nextAbsSerial(users);const ordered=users.slice().sort((a,b)=>new Date(a.createdAt||0)-new Date(b.createdAt||0));ordered.forEach(u=>{if(!u.absId){u.absSerial=serial;u.absId=makeAbsId(u.mobile||u.phone,serial);serial++}});localStorage.setItem("abs_users",JSON.stringify(users));return users}
ensureAbsIds();
function currentUserRecord(){return userRegistry().find(x=>(x.mobile||x.phone)===state.user?.mobile)||null}
function syncUserRegistry(){if(!state.user)return;const users=userRegistry(),t=totals();let u=users.find(x=>x.mobile===state.user.mobile);if(!u){u={name:state.user.name,mobile:state.user.mobile,createdAt:new Date().toISOString()};users.push(u)}u.name=state.user.name;u.absId=u.absId||makeAbsId(u.mobile,u.absSerial||nextAbsSerial(users));u.absSerial=u.absSerial||Number(String(u.absId).match(/(\d{4,})$/)?.[1]||0)||nextAbsSerial(users);u.income=t.income;u.expense=t.expense;u.net=t.net;u.entries=state.data.income.length+state.data.expenses.length+state.data.loans.length+state.data.emi.length+state.data.ledger.length;u.lastActive=new Date().toISOString();localStorage.setItem("abs_users",JSON.stringify(users))}
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const escAttr=s=>esc(s).replace(/`/g,"&#96;");
const uid=()=>Date.now()+Math.floor(Math.random()*999);
function greet(name){const h=new Date().getHours();if(h<12)return`Good Morning, ${name} 👋`;if(h<17)return`Good Afternoon, ${name} 👋`;if(h<21)return`Good Evening, ${name} 👋`;return`Welcome, ${name} 👋`}
function toast(t){const e=$("#toast");e.textContent=t;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),1900)}
function totals(){const income=state.data.income.reduce((a,x)=>a+Number(x.amount||0),0),expense=state.data.expenses.reduce((a,x)=>a+Number(x.amount||0),0),emi=state.data.emi.reduce((a,x)=>a+Number(x.amount||0),0),loan=state.data.loans.reduce((a,x)=>a+Number(x.principal||0),0);return{income,expense,emi,loan,net:income-expense-emi,rate:income?((income-expense-emi)/income)*100:0}}
function ledgerSummary(){let receive=0,pay=0;state.data.ledger.forEach(x=>{const a=Number(x.amount||0);if(["lena","receive"].includes(x.direction))receive+=a;if(x.direction==="received")receive-=a;if(["dena","pay"].includes(x.direction))pay+=a;if(x.direction==="paid")pay-=a});return{receive:Math.max(0,receive),pay:Math.max(0,pay),net:receive-pay}}
function paymentOptions(){return ["UPI","Cash","Bank Transfer","Card","Cheque","Other"]}
function expenseCategories(){ensureData();return state.data.settings.categories||[]}
function incomeCategories(){ensureData();return state.data.settings.incomeCategories||[]}
function typeOptions(){return ["Income","Expense","Ledger"]}
function normalizeDate(v){if(!v)return new Date().toISOString().slice(0,10);v=String(v).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/^(\d{1,2})[-\/]([A-Za-z0-9]+)[-\/](\d{4})$/);if(m){const mon={jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12}[m[2].toLowerCase()];const mm=mon||Number(m[2]);if(mm>=1&&mm<=12)return`${m[3]}-${String(mm).padStart(2,"0")}-${String(m[1]).padStart(2,"0")}`};return v}
function feedbackList(){return JSON.parse(localStorage.getItem("abs_feedback")||"[]")}
function saveFeedbackItem(item){const all=feedbackList();all.unshift(item);localStorage.setItem("abs_feedback",JSON.stringify(all))}
function premiumRequests(){try{return JSON.parse(localStorage.getItem("abs_premium_requests")||"[]")}catch(e){return[]}}
function isVerified(){const u=userRegistry().find(x=>x.mobile===state.user?.mobile);return u?.verified===true}
function requestPremium(){if(!state.user)return; if(isVerified()){toast("Premium is already unlocked");return} const all=premiumRequests();if(all.some(x=>x.mobile===state.user.mobile&&x.status==="pending")){toast("Premium request is already pending");return}all.unshift({id:uid(),name:state.user.name,mobile:state.user.mobile,status:"pending",createdAt:new Date().toISOString()});localStorage.setItem("abs_premium_requests",JSON.stringify(all));renderProfile();toast("Premium request sent to admin") }
function refreshAppData(){if(!state.user)return;ensureData();syncUserRegistry();state.refreshToken=Date.now();render();if(state.tab==="dashboard")toast("Dashboard refreshed")}
function animateMoney(selector,target,duration=900){const el=$(selector);if(!el)return;const start=Number(el.dataset.current||0);const end=Number(target||0);const t0=performance.now();const ease=t=>1-Math.pow(1-t,3);function tick(now){const p=Math.min(1,(now-t0)/duration);const val=start+(end-start)*ease(p);el.textContent=money(val);if(p<1)requestAnimationFrame(tick);else{el.dataset.current=String(end);el.textContent=money(end)}}requestAnimationFrame(tick)}

function openFeedback(){if(!state.user)return;openModal("Feedback",`<div class="feedback-hero"><div class="feedback-icon">✦</div><div><div class="eyebrow">ABS DASHBOARD</div><h3>Tell us what you think</h3><p>Your feedback helps improve the app. You can report a problem, suggest a feature or share your experience.</p></div></div><form id="feedbackForm" class="professional-form"><div class="form-fields"><label class="field"><span>Feedback Type</span><div class="field-control"><select id="feedbackType"><option>Suggestion</option><option>Bug / Problem</option><option>Feature Request</option><option>Experience</option><option>Other</option></select></div></label><label class="field"><span>Rating</span><div class="field-control"><select id="feedbackRating"><option value="5">★★★★★ — Excellent</option><option value="4">★★★★☆ — Good</option><option value="3">★★★☆☆ — Average</option><option value="2">★★☆☆☆ — Needs improvement</option><option value="1">★☆☆☆☆ — Poor</option></select></div></label><label class="field full-field"><span>Your Feedback</span><div class="field-control"><textarea id="feedbackMessage" rows="6" required maxlength="1000" placeholder="Write your feedback here..."></textarea></div></label></div><button class="primary full">SUBMIT FEEDBACK</button></form>`);$("#feedbackForm").onsubmit=e=>{e.preventDefault();const msg=$("#feedbackMessage").value.trim();if(!msg)return toast("Please write your feedback");saveFeedbackItem({id:uid(),name:state.user.name,mobile:state.user.mobile,type:$("#feedbackType").value,rating:Number($("#feedbackRating").value),message:msg,createdAt:new Date().toISOString()});closeModal();toast("Feedback submitted — thank you")}}
function openAdminLogin(){
  openModal("Administrator Access",`<div class="admin-login-head"><div class="admin-lock">⌁</div><div><div class="eyebrow">ABS CONTROL CENTER</div><h3>Administrator access</h3><p>Administrator access is securely verified with Firebase.</p></div></div><form id="adminLoginForm" class="professional-form"><label class="field"><span>Password</span><div class="field-control"><input id="adminPass" type="password" autocomplete="current-password" required placeholder="Enter password"></div></label><button class="primary full">OPEN ADMIN PANEL</button><p id="adminMsg" class="auth-msg"></p></form>`);
  $("#adminLoginForm").onsubmit=async e=>{
    e.preventDefault();
    try{await firebaseAdminLogin($("#adminPass").value);closeModal();state.admin=true;openAdminPanel();}
    catch(err){$("#adminMsg").textContent=err.message||"Administrator authorization failed.";}
  };
}function adminFormatDate(v){if(!v)return "—";const d=new Date(v);return isNaN(d)?String(v):d.toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}
function openAdminPanel(){if(!state.admin)return openAdminLogin();const users=userRegistry(),feedback=feedbackList();const totalIncome=users.reduce((s,u)=>s+Number(u.income||0),0),totalExpense=users.reduce((s,u)=>s+Number(u.expense||0),0);openModal("ABS Admin",`<div class="admin-panel"><div class="admin-hero"><div><div class="eyebrow">ABS CONTROL CENTER</div><h3>Administration</h3><p>Review registered users and all submitted feedback on this device.</p></div><button class="admin-logout" onclick="state.admin=false;closeModal()">LOGOUT</button></div><div class="admin-stats"><div><small>Users</small><b>${users.length}</b></div><div><small>Feedback</small><b>${feedback.length}</b></div><div><small>Total Income</small><b>${money(totalIncome)}</b></div><div><small>Total Expense</small><b>${money(totalExpense)}</b></div></div><div class="admin-section"><div class="admin-section-title"><div><div class="eyebrow">USER MANAGEMENT</div><h4>Registered Users</h4></div><span>${users.length} accounts</span></div>${users.length?`<div class="admin-user-list">${users.map(u=>`<div class="admin-user-card"><div class="admin-user-top"><div class="admin-avatar">${esc((u.name||"U").slice(0,1).toUpperCase())}</div><div><b>${esc(u.name||"User")}</b><small>${esc(u.mobile||"")}</small></div><strong>${money(u.net||0)}</strong></div><div class="admin-user-grid"><span><small>Income</small><b>${money(u.income||0)}</b></span><span><small>Expense</small><b>${money(u.expense||0)}</b></span><span><small>Entries</small><b>${u.entries||0}</b></span><span><small>Last active</small><b>${esc(adminFormatDate(u.lastActive))}</b></span></div><div class="admin-user-actions"><span class="password-safe">🔒 Password hidden for security</span><button onclick="adminResetUserPassword(${JSON.stringify(u.mobile)})">RESET PASSWORD</button></div></div>`).join("")}</div>`:`<div class="admin-empty">No registered users yet.</div>`}</div><div class="admin-section"><div class="admin-section-title"><div><div class="eyebrow">USER VOICE</div><h4>All Feedback</h4></div><span>${feedback.length} submissions</span></div>${feedback.length?`<div class="feedback-admin-list">${feedback.map(f=>`<div class="feedback-admin-card"><div class="feedback-admin-top"><div><b>${esc(f.name||"User")}</b><small>${esc(f.mobile||"")} · ${esc(f.type||"Feedback")}</small></div><div class="feedback-stars">${"★".repeat(Number(f.rating||0))}${"☆".repeat(5-Number(f.rating||0))}</div></div><p>${esc(f.message||"")}</p><div class="feedback-admin-foot"><span>${esc(adminFormatDate(f.createdAt))}</span><button onclick="deleteFeedback(${JSON.stringify(f.id)})">DELETE</button></div></div>`).join("")}</div>`:`<div class="admin-empty">No feedback submitted yet.</div>`}</div><div class="admin-security-note"><b>Security note</b><span>User passwords are not displayed in the admin panel. The panel provides a controlled password reset instead.</span></div></div>`)}
function adminResetUserPassword(mobile){if(!state.admin)return;openModal("Reset User Password",`<div class="workspace-hero"><div class="workspace-icon">🔒</div><div><div class="eyebrow">ACCOUNT SECURITY</div><h3>Set a new password</h3><p>Password for <b>${esc(mobile)}</b> will be replaced. The existing password is never revealed.</p></div></div><form id="adminResetForm" class="professional-form"><label class="field"><span>New Password</span><div class="field-control"><input id="adminNewPassword" type="password" minlength="6" required placeholder="Minimum 6 characters"></div></label><label class="field"><span>Confirm Password</span><div class="field-control"><input id="adminNewPassword2" type="password" minlength="6" required placeholder="Repeat password"></div></label><button class="primary full">UPDATE PASSWORD</button></form>`);$("#adminResetForm").onsubmit=e=>{e.preventDefault();const a=$("#adminNewPassword").value,b=$("#adminNewPassword2").value;if(a!==b)return toast("Passwords do not match");localStorage.setItem(`abs_password_${mobile}`,a);closeModal();toast("User password updated");openAdminPanel()}}
function deleteFeedback(id){if(!state.admin)return;if(!confirm("Delete this feedback?"))return;localStorage.setItem("abs_feedback",JSON.stringify(feedbackList().filter(x=>x.id!==id)));openAdminPanel();toast("Feedback deleted")}
function setup(){document.body.classList.toggle("light",state.theme==="light");if(state.user){const rec=ensureAbsIds().find(u=>u.mobile===state.user.mobile);if(rec)state.user.absId=rec.absId;const exists=userRegistry().some(u=>u.mobile===state.user.mobile);if(!exists){clearSession();state.user=null;state.data=EMPTY_DATA();}else{ensureData();$("#authScreen").classList.add("hidden");$("#mainApp").classList.remove("hidden");$("#greeting").textContent=greet(state.user.name);render();return}}$("#authScreen").classList.remove("hidden");$("#mainApp").classList.add("hidden")}
$("#showRegister").onclick=()=>{$("#loginPanel").classList.add("hidden");$("#registerPanel").classList.remove("hidden")};$("#showLogin").onclick=()=>{$("#registerPanel").classList.add("hidden");$("#loginPanel").classList.remove("hidden")};
$("#registerForm").onsubmit=async e=>{e.preventDefault();const n=$("#regName").value.trim(),m=$("#regMobile").value.trim(),p=$("#regPassword").value,c=$("#regConfirm").value;$("#regMsg").textContent="";if(!/^[6-9]\d{9}$/.test(m))return $("#regMsg").textContent="Enter a valid 10-digit Indian mobile number.";if(p!==c)return $("#regMsg").textContent="Passwords do not match.";if(!firebaseAdminReady())return $("#regMsg").textContent="Firebase is not loaded. Please refresh the app.";const users=userRegistry();if(users.some(u=>u.mobile===m))return $("#regMsg").textContent="An account with this mobile number already exists.";const email=`${m}@absdashboard.app`;try{const cred=await firebase.auth().createUserWithEmailAndPassword(email,p);const serial=nextAbsSerial(users);const absId=makeAbsId(m,serial);await firebase.firestore().collection("users").doc(cred.user.uid).set({name:n,mobile:m,absId,absSerial:serial,createdAt:new Date().toISOString(),premium:false,verified:false,income:0,expense:0,net:0,entries:0,lastActive:new Date().toISOString()},{merge:true});state.user={name:n,mobile:m,absId,uid:cred.user.uid};state.data=EMPTY_DATA();ensureData();save();persistSession(state.user);localStorage.setItem(`abs_password_${m}`,p);users.push({name:n,mobile:m,absSerial:serial,absId,createdAt:new Date().toISOString(),income:0,expense:0,net:0,entries:0,uid:cred.user.uid});localStorage.setItem("abs_users",JSON.stringify(users));setup()}catch(err){console.error("Firebase registration failed",err);$("#regMsg").textContent=err.code==="auth/email-already-in-use"?"An account with this mobile number already exists.":(err.message||"Registration failed. Please try again.")}}
$("#loginForm").onsubmit=async e=>{
  e.preventDefault();
  const m=$("#loginMobile").value.trim(),p=$("#loginPassword").value;
  $("#authMsg").textContent="";

  /* Hidden administrator route: no admin button/text is shown on login. */
  if(m==="Shkadmin"){
    try{
      await firebaseAdminLogin(p);
      state.user=null;
      state.admin=true;
      closeModal();
      $("#authScreen").classList.add("hidden");
      $("#mainApp").classList.add("hidden");
      openAdminPanel();
    }catch(err){
      $("#authMsg").textContent=err.message||"Incorrect login details.";
    }
    return;
  }

  if(!/^[6-9]\d{9}$/.test(m))return $("#authMsg").textContent="Enter a valid 10-digit Indian mobile number.";
  const users=userRegistry(),u=users.find(x=>x.mobile===m);const stored=localStorage.getItem(`abs_password_${m}`);
  if(!u||stored===null)return $("#authMsg").textContent="Account not found on this device.";
  if(p!==stored)return $("#authMsg").textContent="Incorrect mobile number or password.";
  state.user={name:u.name,mobile:u.mobile};persistSession(state.user);ensureData();setup();
};
$("#themeBtn").onclick=()=>{state.theme=state.theme==="dark"?"light":"dark";localStorage.setItem("abs_theme",state.theme);setup()};
$("#refreshBtn").onclick=refreshAppData;
function goTab(tab){try{state.tab=tab||"dashboard";document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.tab===state.tab));render();}catch(err){console.error("ABS navigation error",err);if(state.tab==="profile")renderProfile();else toast("Unable to open this section. Please try again.")}}
document.querySelectorAll(".nav-item").forEach(b=>{b.type="button";b.addEventListener("click",e=>{e.preventDefault();goTab(b.dataset.tab);});});
function openAvatarPicker(){openModal("Profile Picture",`<div class="avatar-picker"><div class="avatar-upload-hero"><div class="avatar-upload-icon">📷</div><div><b>Update your profile photo</b><p class="muted">Upload a photo or choose an avatar below.</p></div></div><label class="upload-photo">📷 Upload Photo<input id="avatarFile" type="file" accept="image/*" hidden></label><p class="muted avatar-choice-label">Choose an avatar</p><div class="avatar-options big"><button type="button" onclick="setAvatar('👦')">👦</button><button type="button" onclick="setAvatar('👧')">👧</button><button type="button" onclick="setAvatar('👨')">👨</button><button type="button" onclick="setAvatar('👩')">👩</button><button type="button" onclick="setAvatar('🙂')">🙂</button></div></div>`);$("#avatarFile").onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{localStorage.setItem("abs_avatar",r.result);localStorage.removeItem("abs_avatar_emoji");closeModal();renderProfile();toast("Profile photo updated")};r.readAsDataURL(f)}}
function setAvatar(v){localStorage.setItem("abs_avatar_emoji",v);localStorage.removeItem("abs_avatar");closeModal();renderProfile();toast("Avatar updated")}
function toggleTheme(){state.theme=state.theme==="dark"?"light":"dark";localStorage.setItem("abs_theme",state.theme);setup();}
function openProfileEdit(){
  const rec=currentUserRecord()||{};
  const avatar=localStorage.getItem("abs_avatar");
  const emoji=localStorage.getItem("abs_avatar_emoji")||String(state.user.name||"U").slice(0,1).toUpperCase();
  const screenEl=document.getElementById("screen");
  if(!screenEl)return;
  screenEl.innerHTML=`<div class="profile-edit-page">
    <button type="button" class="about-back-btn" id="profileEditBack">‹ <span>Back</span></button>
    <div class="about-detail-hero profile-edit-page-hero"><div class="about-detail-icon">✎</div><div><div class="eyebrow">EDIT PROFILE</div><h1>Personal details</h1><p>Update your name and profile picture.</p></div></div>
    <form id="editProfilePage" class="professional-form profile-edit-form">
      <div class="profile-edit-photo-block">
        <button type="button" class="profile-edit-photo-circle" id="profilePhotoChoose">${avatar?`<img src="${esc(avatar)}" alt="Profile">`:esc(emoji)}</button>
        <div><b>Profile Photo</b><p class="muted">Tap the photo to change it.</p></div>
        <input id="profilePhotoFile" type="file" accept="image/*" hidden>
      </div>
      <label class="field"><span>Full Name</span><div class="field-control"><input id="editName" value="${esc(state.user.name)}" required autocomplete="name"></div></label>
      <label class="field"><span>ABS ID</span><div class="field-control"><input value="${esc(rec.absId||state.user.absId||"")}" readonly aria-readonly="true"></div></label>
      <p class="profile-readonly-note">ABS ID is assigned and can only be changed by ABS Admin.</p>
      <button class="primary full" type="submit">SAVE CHANGES</button>
    </form></div>`;
  $("#profileEditBack").onclick=()=>renderProfile();
  $("#profilePhotoChoose").onclick=()=>$("#profilePhotoFile").click();
  $("#profilePhotoFile").onchange=e=>{
    const f=e.target.files?.[0]; if(!f)return;
    if(!f.type.startsWith("image/"))return toast("Please choose an image");
    const r=new FileReader();
    r.onload=()=>{localStorage.setItem("abs_avatar",r.result);localStorage.removeItem("abs_avatar_emoji");$("#profilePhotoChoose").innerHTML=`<img src="${esc(r.result)}" alt="Profile">`;toast("Profile photo selected")};
    r.readAsDataURL(f);
  };
  $("#editProfilePage").onsubmit=e=>{
    e.preventDefault();
    const n=$("#editName").value.trim();
    if(!n)return toast("Enter your name");
    const mobile=state.user.mobile;
    const users=userRegistry();
    const u=users.find(x=>x.mobile===mobile);
    if(!u)return toast("Account not found");
    u.name=n;
    u.absId=u.absId||state.user.absId||makeAbsId(mobile,u.absSerial||nextAbsSerial(users));
    localStorage.setItem("abs_users",JSON.stringify(users));
    state.user={...state.user,name:n,mobile,absId:u.absId||state.user.absId};
    persistSession(state.user); ensureData();
    $("#greeting").textContent=greet(n);
    renderProfile(); toast("Profile updated successfully");
  };
}
function openAboutApp(){
  const screenEl=document.getElementById("screen");
  if(!screenEl)return;
  screenEl.innerHTML=`<div class="about-detail-page"><button type="button" class="about-back-btn" id="aboutBack">‹ <span>Back</span></button><div class="about-detail-hero"><div class="about-detail-icon logo-mark"><img src="assets/abs-logo.png" alt="ABS" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span>ABS</span></div><div><div class="eyebrow">ABOUT ABS DASHBOARD</div><h1>Personal finance, made simple.</h1><p>Track. Understand. Manage.</p></div></div><article class="about-detail-copy"><p><strong>ABS DASHBOARD</strong> is your personal finance companion, designed to bring your income, expenses, savings, loans, EMI and Lena / Dena records together in one clear place.</p><p>Use your dashboard to understand your financial position, explore your spending trends and keep your records organized. ABS AI can also analyse your saved account data and answer questions in a simple, useful way.</p><p>Your financial data stays connected to your ABS Dashboard account so you can review your records whenever you need them.</p></article><div class="about-detail-footer"><span>ABS DASHBOARD</span><span>© 2026</span></div></div>`;
  $("#aboutBack").onclick=()=>renderProfile();
  renderFooter();
}
function openPassword(){openModal("Change Password",`<div class="profile-edit-hero"><div class="profile-edit-icon">🔒</div><div><div class="eyebrow">ACCOUNT SECURITY</div><h3>Change your password</h3><p>Use a strong password that only you know.</p></div></div><form id="passForm" class="professional-form"><label class="field"><span>Current Password</span><div class="field-control"><input id="oldPass" type="password" autocomplete="current-password" required></div></label><label class="field"><span>New Password</span><div class="field-control"><input id="newPass" type="password" minlength="6" autocomplete="new-password" required></div></label><label class="field"><span>Confirm Password</span><div class="field-control"><input id="newPass2" type="password" minlength="6" autocomplete="new-password" required></div></label><button class="primary full">UPDATE PASSWORD</button></form>`);$("#passForm").onsubmit=e=>{e.preventDefault();if($("#oldPass").value!==localStorage.getItem(`abs_password_${state.user.mobile}`))return toast("Current password is incorrect");if($("#newPass").value!==$("#newPass2").value)return toast("Passwords do not match");localStorage.setItem(`abs_password_${state.user.mobile}`,$("#newPass").value);closeModal();toast("Password changed successfully")}}
function exportData(){exportPDF()}
function renderProfile(){
  const screenEl=document.getElementById("screen");
  if(!screenEl)return;
  try{
    if(!state.user){state.tab="dashboard";return renderDashboard();}
    const avatar=localStorage.getItem("abs_avatar");
    const emoji=localStorage.getItem("abs_avatar_emoji")||String(state.user.name||"U").slice(0,1).toUpperCase();
    const verified=isVerified();
    const req=premiumRequests().find(x=>x.mobile===state.user.mobile&&x.status==="pending");
    const premiumCard=`<section class="premium-access-card ${verified?'unlocked':''}"><div class="premium-inline-left"><span class="premium-kicker">ABS PREMIUM</span><h3>${verified?'Premium Unlocked':'Unlock Premium'}</h3></div>${verified?`<div class="premium-status-ok">UNLOCKED</div>`:`<button type="button" class="premium-request-btn ${req?'pending':''}" data-profile-action="premium" ${req?'disabled':''}>${req?'REQUEST SENT':'REQUEST'} <span>${req?'✓':'→'}</span></button>`}</section>`;
    screenEl.innerHTML=`<div class="page-title">Profile</div><p class="page-sub">Account, security and preferences.</p>
      <section class="profile-premium profile-identity-row"><div class="profile-avatar">${avatar?`<img src="${esc(avatar)}" alt="Profile">`:esc(emoji)}</div><div class="profile-identity"><div class="profile-name">${esc(state.user.name)} ${verified?'<span class="verified-badge" aria-label="Verified"><svg viewBox="0 0 24 24"><path d="M7 12.5l3.1 3.1L17.5 8.5"/></svg></span>':''}</div><div class="profile-mobile">${esc(currentUserRecord()?.absId||state.user.absId||"")}</div></div><button type="button" class="profile-edit-inline" id="profileEditBtn" onclick="openProfileEdit(); return false;">Edit Profile <span>›</span></button></section>
      ${premiumCard}
      <div class="menu">
        <button type="button" onclick="openPassword()"><span>🔒 Change Password</span><span>›</span></button>
        <button type="button" data-profile-action="theme"><span>◐ Theme</span><span>${esc(state.theme)}</span></button>
        <button type="button" data-profile-action="export"><span>⇩ Export My Data</span><span>›</span></button>
        <button type="button" class="about-app-option" onclick="openAboutApp()"><span><b>About App</b><small>Learn more about ABS Dashboard</small></span><span>›</span></button>
        <button type="button" class="danger" data-profile-action="logout"><span>Logout</span><span>→</span></button>
      </div>`; screenEl.querySelectorAll('[data-profile-action]').forEach(btn=>btn.addEventListener('click',()=>{
      const a=btn.dataset.profileAction;
      if(a==='edit')openProfileEdit();
      else if(a==='password')openPassword();
      else if(a==='theme')toggleTheme();
      else if(a==='export')exportData();
      else if(a==='logout')logout();
      else if(a==='avatar')openAvatarPicker();
      else if(a==='premium')requestPremium();
      else if(a==='about')openAboutApp();
    }));
  }catch(err){
    console.error("ABS profile render error",err);
    screenEl.innerHTML=`<div class="page-title">Profile</div><p class="page-sub">Account, security and preferences.</p><section class="panel" style="padding:22px"><div class="profile-premium"><div class="profile-avatar">${esc(String(state.user?.name||"U").slice(0,1).toUpperCase())}</div><div><div class="profile-name">${esc(state.user?.name||"User")}</div><div class="profile-mobile">${esc(currentUserRecord()?.absId||state.user?.absId||"")}</div></div></div><button type="button" class="primary full" id="profileRetry">RELOAD PROFILE</button></section>`;
    document.getElementById("profileRetry")?.addEventListener("click",()=>renderProfile());
  }
}

function render(){document.body.classList.toggle("ai-open",state.tab==="ai");if(state.tab!=="ai")document.body.classList.remove("ai-open");if(state.tab==="dashboard")renderDashboard();if(state.tab==="explore")renderExplore();if(state.tab==="ai")renderAI();if(state.tab==="profile")renderProfile();renderFooter()}
function renderFooter(){const screen=$("#screen");if(!screen)return;screen.querySelector(".app-footer")?.remove();screen.insertAdjacentHTML("beforeend",`<footer class="app-footer">© 2026 ABS DASHBOARD. All Rights Reserved. <span>Riyaz Dev</span></footer>`)}
function metric(icon,label,value,sub){return `<div class="metric premium-metric"><div class="label">${icon} ${esc(label)}</div><div class="value">${money(value)}</div><div class="trend">${esc(sub||"")}</div></div>`}
function monthKey(v){const d=new Date(v);if(isNaN(d))return null;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function monthLabel(k){const [y,m]=String(k).split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('en-IN',{month:'short',year:'2-digit'}).replace(' ','-')}
function monthlyFlow(){const now=new Date();const end=new Date(now.getFullYear(),now.getMonth(),1);const keys=[];for(let i=11;i>=0;i--){const d=new Date(end.getFullYear(),end.getMonth()-i,1);keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}const income=Object.fromEntries(keys.map(k=>[k,0])),expense=Object.fromEntries(keys.map(k=>[k,0])),emi=Object.fromEntries(keys.map(k=>[k,0]));state.data.income.forEach(x=>{const k=monthKey(x.date||x.createdAt);if(k&&income[k]!==undefined)income[k]+=Number(x.amount||0)});state.data.expenses.forEach(x=>{const k=monthKey(x.date||x.createdAt);if(k&&expense[k]!==undefined)expense[k]+=Number(x.amount||0)});state.data.emi.forEach(x=>{const k=monthKey(x.date||x.createdAt);if(k&&emi[k]!==undefined)emi[k]+=Number(x.amount||0)});return{keys,labels:keys.map(monthLabel),income:keys.map(k=>income[k]),expense:keys.map(k=>expense[k]),emi:keys.map(k=>emi[k])}}
function chartBuckets(range){
 const now=new Date(); now.setHours(23,59,59,999);
 const rows=[...state.data.income.map(x=>({...x,_kind:"income"})),...state.data.expenses.map(x=>({...x,_kind:"expense"})),...state.data.emi.map(x=>({...x,_kind:"emi"}))];
 const daily=range==='1m';
 let labels=[],keys=[];
 if(daily){
   for(let i=29;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10);keys.push(k);labels.push(d.toLocaleDateString('en-IN',{day:'2-digit',month:'short'}));}
 }else{
   const months=range==='6m'?6:range==='1y'?12:null;
   let first;
   if(months){first=new Date(now.getFullYear(),now.getMonth()-months+1,1);}
   else{
     const dates=rows.map(x=>normalizeDate(x.date||x.createdAt)).filter(Boolean).sort();
     first=dates.length?new Date(String(dates[0]).slice(0,7)+'-01'):new Date(now.getFullYear(),now.getMonth(),1);
   }
   const cursor=new Date(first.getFullYear(),first.getMonth(),1);
   while(cursor<=now){const k=`${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,'0')}`;keys.push(k);labels.push(cursor.toLocaleDateString('en-IN',{month:'short',year:'2-digit'}).replace(' ','-'));cursor.setMonth(cursor.getMonth()+1);}
 }
 const income=keys.map(()=>0),expense=keys.map(()=>0),emi=keys.map(()=>0);
 rows.forEach(x=>{const d=normalizeDate(x.date||x.createdAt);if(!d)return;const k=daily?d:d.slice(0,7);const i=keys.indexOf(k);if(i<0)return;const amount=Number(x.amount||0);if(x._kind==='income')income[i]+=amount;else if(x._kind==='expense')expense[i]+=amount;else emi[i]+=amount;});
 return {labels,income,expense,emi};
}
function setChartRange(range){state.chartRange=range;renderDashboard()}
function renderDashboard(){
 const t=totals(),l=ledgerSummary();
 const balance=Number(t.net||0)+Number(l.receive||0)-Number(l.pay||0);
 const recent=[...state.data.income.map(x=>({...x,_type:'income'})),...state.data.expenses.map(x=>({...x,_type:'expense'})),...state.data.ledger.map(x=>({...x,_type:'ledger'}))].sort((a,b)=>String(b.date||b.createdAt||'').localeCompare(String(a.date||a.createdAt||''))).slice(0,4);
 const recentHtml=recent.length?recent.map(x=>{const type=x._type==='income'?'income':x._type==='expense'?'expense':'ledger';const icon=type==='income'?'↗':type==='expense'?'↘':'↔';const title=type==='income'?(x.source||'Income'):type==='expense'?(x.category||'Expense'):(x.person||x.directionLabel||'Ledger');const amount=Number(x.amount||0);const sign=type==='income'?'+':type==='expense'?'-':(String(x.direction||x.directionLabel||'').toLowerCase().includes('receive')?'+':'-');return `<div class="activity"><div class="dot ${type}">${icon}</div><div class="info"><b>${esc(title)}</b><small>${esc(x.description||x.date||'')}</small></div><strong class="${sign==='+'?'positive':'negative'}">${sign}${money(amount)}</strong></div>`}).join(''):`<div class="empty-state"><span>＋</span><b>No transactions yet</b><p>Add your first income or expense from Explore.</p></div>`;
 const saveRate=t.income?Math.max(-100,Math.min(100,(t.net/t.income)*100)):0;const score=Math.max(0,Math.min(100,Math.round(50+saveRate/2-(t.expense>t.income&&t.income?15:0))));const scoreText=score>=75?'Healthy':score>=50?'Balanced':'Needs attention';
 const range=state.chartRange||'6m';
 $("#screen").innerHTML=`${renderAds()}<section class="simple-dashboard-hero"><div class="simple-hero-top"><div><h1>ABS DASHBOARD</h1><p>Track. Understand. Manage.</p></div><div class="score-pill"><span>${score}</span><small>${scoreText}</small></div></div><div class="balance-label">AVAILABLE BALANCE</div><div class="balance-value" id="dashBalance" data-current="0">${money(0)}</div><div class="balance-note">Income + money to receive − expenses − money to pay</div></section><div class="simple-stats"><button onclick="openAdd('income')"><span class="stat-icon income">↗</span><small>Income</small><b class="dash-money" data-target="${Number(t.income||0)}">${money(0)}</b></button><button onclick="openAdd('expense')"><span class="stat-icon expense">↘</span><small>Expense</small><b class="dash-money" data-target="${Number(t.expense||0)}">${money(0)}</b></button><button onclick="openFeature('report')"><span class="stat-icon savings">◌</span><small>Savings</small><b class="dash-money" data-target="${Number(t.net||0)}">${money(0)}</b></button></div><div class="section-head simple-section-head"><div><h2>Cash Flow</h2><p class="section-sub">Actual records · ${range==='1m'?'daily':range==='6m'?'6 months':range==='1y'?'1 year':'all history'}</p></div><button onclick="openStatement()">Statement</button></div><div class="chart-range-bar"><button class="${range==='1m'?'active':''}" onclick="setChartRange('1m')">1M</button><button class="${range==='6m'?'active':''}" onclick="setChartRange('6m')">6M</button><button class="${range==='1y'?'active':''}" onclick="setChartRange('1y')">1Y</button><button class="${range==='all'?'active':''}" onclick="setChartRange('all')">ALL</button></div><div class="panel simple-chart-panel"><canvas id="flowChart"></canvas></div><div class="section-head simple-section-head"><div><h2>Recent Activity</h2><p class="section-sub">Latest money movements</p></div><button onclick="openFeature('history')">View all</button></div><div class="panel list simple-activity-list">${recentHtml}</div><div class="dashboard-mini-links"><button onclick="openFeature('loan')">Loan & EMI <span>→</span></button><button onclick="openFeature('ledger')">Lena / Dena <span>→</span></button></div>`;setTimeout(()=>{drawCharts(range);animateMoney("#dashBalance",balance,1050);document.querySelectorAll(".dash-money").forEach((el,i)=>animateMoneyEl(el,Number(el.dataset.target||0),850+i*100))},60)}
function animateMoneyEl(el,target,duration=900){const t0=performance.now();const ease=t=>1-Math.pow(1-t,3);function tick(now){const p=Math.min(1,(now-t0)/duration);el.textContent=money(target*ease(p));if(p<1)requestAnimationFrame(tick);else el.textContent=money(target)}requestAnimationFrame(tick)}
function drawCharts(range=state.chartRange||'6m'){const f=chartBuckets(range),ctx=$("#flowChart");if(ctx){if(window._absFlowChart)window._absFlowChart.destroy();window._absFlowChart=new Chart(ctx,{type:"line",data:{labels:f.labels,datasets:[{label:"Income",data:f.income,tension:.28,borderWidth:3,pointRadius:range==='1m'?1.5:2,fill:false},{label:"Expense",data:f.expense,tension:.28,borderWidth:3,pointRadius:range==='1m'?1.5:2,fill:false},{label:"EMI",data:f.emi,tension:.28,borderWidth:2,pointRadius:range==='1m'?1.5:2,borderDash:[5,4],fill:false}]},options:{responsive:true,maintainAspectRatio:false,animation:{duration:350},interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:getComputedStyle(document.body).color,font:{size:9}}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${money(c.parsed.y)}`}}},scales:{x:{grid:{display:false},ticks:{color:"#8290a8",font:{size:9},maxRotation:0,maxTicksLimit:range==='1m'?8:12}},y:{beginAtZero:true,grid:{color:"rgba(128,140,170,.12)"},ticks:{color:"#8290a8",font:{size:9},callback:v=>money(v)}}}}})}}
function renderExplore(){const a=[["💰","Add Income","Salary, bonus & other income","income"],["💸","Add Expense","Track spending by category","expense"],["📥","Bulk Data","Add many old records at once","bulk"],["🏦","Add Loan","Principal, interest & tenure","loan"],["💳","Add EMI","Record repayment","emi"],["📅","Loan Schedule","Principal & interest timeline","schedule"],["👥","People","Name, phone & balances","people"],["🤝","Ledger","Lena / Dena — receive & pay","ledger"],["🎯","Budget","Monthly spending limits","budget"],["💼","Career","Jobs & salary history","career"],["📊","Reports","Income, expense & Lena/Dena report","report"],["🧾","Statement","Filter by date and export a clean statement","statement"],["⚙️","Settings","Personalize the app","settings"],["🗂","Categories","Add your own income & expense categories","categories"],["🕘","History","View all income, expense & ledger records","history"],["✎","Edit Records","Correct saved income, expense & ledger entries","editrecords"],["💬","Feedback","Share your experience, report a problem or suggest a feature","feedback"],["📘","Guide","Learn every feature","guide"]];$("#screen").innerHTML=`<div class="explore-head"><div><div class="eyebrow">YOUR FINANCIAL TOOLKIT</div><div class="page-title">Explore</div><p class="page-sub">Start from zero or import your old financial history in bulk.</p></div><div class="explore-count">${a.length}<small>TOOLS</small></div></div><div class="quick-import-banner"><div><b>Have old data?</b><small>Use Bulk Data to bring previous records into ABS without adding them one by one.</small></div><button onclick="openFeature('bulk')">IMPORT</button></div><div class="explore-grid professional-grid">${a.map((x,i)=>`<button class="action-card professional-action" style="animation-delay:${i*30}ms" onclick="openFeature('${x[3]}')"><div class="action-top"><div class="ico">${x[0]}</div><span>↗</span></div><b>${x[1]}</b><small>${x[2]}</small></button>`).join("")}</div>`}
function openFeature(type){const info={schedule:["📅","LOAN PLANNER","Loan Schedule","Month-wise EMI, interest and outstanding balance."],people:["👥","PEOPLE & BALANCES","People","Save name, mobile number and each person's current balance."],ledger:["🤝","LENA / DENA","Ledger","Track money you need to receive and money you need to pay."],budget:["🎯","SMART BUDGET","Budget","Set limits and keep monthly spending under control."],career:["💼","CAREER HISTORY","Career & Salary","Keep work history, roles and salary records together."],report:["📊","FINANCIAL INSIGHTS","Reports","See income, expenses, payment modes and Lena/Dena balances."],settings:["⚙️","PERSONALIZE","Settings","Control categories and app preferences."],guide:["📘","GET STARTED","Guide","Learn the ABS Dashboard in a few simple steps."],bulk:["📥","BULK IMPORT","Old Data Import","Add previous records quickly using a mobile-friendly CSV format."]};if(["income","expense","loan","emi"].includes(type))return openAdd(type);if(type==="bulk")return openBulk();if(type==="people")return openPeople();if(type==="ledger")return openLedger();if(type==="categories")return openCategories();if(type==="history")return openHistory();if(type==="editrecords")return openEditRecords();if(type==="feedback")return openFeedback();if(type==="statement")return openStatement();const i=info[type]||["✦","ABS DASHBOARD","Module","Manage this section from one place."];let body="";if(type==='schedule'){const loans=state.data.loans||[];body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="mini-stat-grid"><div><b>${loans.length}</b><small>Active loans</small></div><div><b>${money(loans.reduce((a,x)=>a+Number(x.emi||0),0))}</b><small>Total EMI</small></div></div><div class="workspace-list">${loans.map(l=>`<div class="record-card"><div class="record-icon">🏦</div><div class="record-main"><b>${esc(l.name||'Loan')}</b><small>${esc(l.lender||'Lender')} · ${l.tenure||0} months</small></div><div class="record-value">${money(l.emi||0)}<small>EMI</small></div></div>`).join('')||`<div class="empty-state large"><span>📅</span><b>No loan schedule yet</b><p>Add a loan to start repayment planning.</p></div>`}</div>`}else if(type==='budget'){const budgets=state.data.settings?.budgets||{};body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="workspace-list">${Object.entries(budgets).map(([k,v])=>`<div class="budget-row"><div><b>${esc(k)}</b><small>Monthly limit</small></div><strong>${money(v)}</strong></div>`).join('')||`<div class="empty-state large"><span>🎯</span><b>No budgets configured</b><p>Your budget categories will appear here.</p></div>`}</div>`}else if(type==='career'){const rows=state.data.career||[];body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="workspace-list">${rows.map(x=>`<div class="record-card"><div class="record-icon">💼</div><div class="record-main"><b>${esc(x.company||'Company')}</b><small>${esc(x.designation||'Role')}</small></div><div class="record-value">${money(x.salary||0)}<small>Salary</small></div></div>`).join('')||`<div class="empty-state large"><span>💼</span><b>No career records</b><p>Add your job and salary history when needed.</p></div>`}</div>`}else if(type==='report'){const t=totals(),l=ledgerSummary();body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="insight-grid"><div><small>Income</small><b>${money(t.income)}</b></div><div><small>Expenses</small><b>${money(t.expense)}</b></div><div><small>Net savings</small><b>${money(t.net)}</b></div><div><small>Loan principal</small><b>${money(t.loan)}</b></div><div><small>🟢 To receive</small><b>${money(l.receive)}</b></div><div><small>🔴 To pay</small><b>${money(l.pay)}</b></div></div><div class="insight-note"><span>✓</span><div><b>Live report</b><p>Totals update from your saved transactions, payment modes and Lena/Dena entries.</p></div></div>`}else if(type==='settings'){body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="settings-stack"><div class="setting-card"><span>◐</span><div><b>Appearance</b><small>Current theme: ${esc(state.theme)}</small></div><button onclick="toggleTheme();closeModal();">Change</button></div><div class="setting-card"><span>🧹</span><div><b>Start fresh</b><small>Clear all financial records and keep your account.</small></div><button onclick="resetFinancialData()">RESET</button></div><div class="setting-card"><span>🗂</span><div><b>Categories</b><small>Add or remove your own income and expense categories.</small></div><button onclick="closeModal();openCategories()">Manage</button></div><div class="setting-card"><span>🕘</span><div><b>History</b><small>View and edit all recorded transactions.</small></div><button onclick="closeModal();openHistory()">Open</button></div><div class="setting-card"><span>⇩</span><div><b>ABS Statement</b><small>Export a bank-style PDF statement.</small></div><button onclick="exportPDF()">PDF</button></div></div>`}else{body=`<div class="workspace-hero"><div class="workspace-icon">${i[0]}</div><div><div class="eyebrow">${i[1]}</div><h3>${i[2]}</h3><p>${i[3]}</p></div></div><div class="guide-steps"><div><span>01</span><b>Start with zero</b><p>A new account has no demo transactions. Add your own records or import old data.</p></div><div><span>02</span><b>Use payment modes</b><p>UPI, Cash, Bank Transfer, Card, Cheque and Other are available wherever money is recorded.</p></div><div><span>03</span><b>Track people</b><p>Save a person's name and mobile number, then record Lena, Dena, Received or Paid entries.</p></div></div>`}openModal(i[2],`${body}<button class="primary full feature-action" onclick="closeModal()">DONE</button>`)}
function openAdd(type){const configs={income:["Add Income","Record money that came in",[["date","Date","date","When did you receive it?"],["source","Income Type","select-options",incomeCategories().join("|")],["description","Description","text","Add a short note"],["amount","Amount (₹)","number","Enter amount"],["mode","Payment Mode","select-options",paymentOptions().join("|")]]],expense:["Add Expense","Record where your money went",[["date","Date","date","When was this paid?"],["category","Category","select-options",expenseCategories().join("|")],["description","Description","text","What was it for?"],["amount","Amount (₹)","number","Enter amount"],["mode","Payment Mode","select-options",paymentOptions().join("|")]]],loan:["Add Loan","Create a clear repayment plan",[["name","Loan Name","text","e.g. Home Loan"],["type","Loan Type","select-options","Personal Loan|Home Loan|Vehicle Loan|Education Loan|Business Loan|Other"],["lender","Lender / Bank","text","Bank or lender name"],["principal","Principal (₹)","number","Original loan amount"],["rate","Interest Rate %","number","Annual interest rate"],["tenure","Tenure (months)","number","Total months"],["emi","Monthly EMI (₹)","number","EMI amount"],["start","EMI Start Date","date","When EMI begins"]]],emi:["Add EMI","Record a repayment",[["date","Payment Date","date","When was EMI paid?"],["loan","Loan","select-options",(state.data.loans.map(x=>x.name||"Loan").join("|")||"No loan added")],["amount","Amount (₹)","number","EMI amount"],["mode","Payment Mode","select-options",paymentOptions().join("|")],["remarks","Remarks","text","Optional note"]]]};const [title,subtitle,fields]=configs[type],icon={income:'↗',expense:'↘',loan:'⌂',emi:'◫'}[type];openModal(title,`<div class="form-hero"><div class="form-hero-icon">${icon}</div><div><div class="eyebrow">ABS · ${type.toUpperCase()}</div><p>${subtitle}</p></div></div><form id="dynamicForm" class="professional-form"><div class="form-fields">${fields.map(f=>fieldHtml(f)).join('')}</div><div class="form-footer"><button class="primary full" type="submit">SAVE ${type.toUpperCase()} <span>→</span></button><small>Your record is saved instantly on this device.</small></div></form>`);const dateField=$("#dynamicForm input[name='date']");if(dateField)dateField.value=new Date().toISOString().slice(0,10);$("#dynamicForm").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),o={id:uid()};fields.forEach(f=>o[f[0]]=fd.get(f[0]));if(type==="income")state.data.income.push({...o,amount:Number(o.amount)});if(type==="expense")state.data.expenses.push({...o,amount:Number(o.amount)});if(type==="loan")state.data.loans.push({...o,principal:Number(o.principal),rate:Number(o.rate),tenure:Number(o.tenure),emi:Number(o.emi)});if(type==="emi")state.data.emi.push({...o,amount:Number(o.amount)});save();closeModal();toast("Saved successfully");render()}}
function fieldHtml(f){if(f[2]==="select-options"){const opts=(f[3]||"").split("|").filter(Boolean);return`<label class="field"><span>${f[1]}</span><div class="field-control"><select name="${f[0]}" required>${opts.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("")}</select></div></label>`}const inputmode=f[2]==='number'?' inputmode="decimal"':'';const step=f[2]==='number'?' step="0.01"':'';return`<label class="field"><span>${f[1]}</span><div class="field-control"><input name="${f[0]}" type="${f[2]}" placeholder="${esc(f[3]||'')}"${inputmode}${step} ${f[0]==="amount"?"min='0'":""} required></div></label>`}
function openPeople(){const p=state.data.people||[];const rows=p.map(x=>{const s=personBalance(x.name);return`<div class="record-card"><div class="record-icon">👤</div><div class="record-main"><b>${esc(x.name)}</b><small>📱 ${esc(x.phone||"No number")} · ${esc(x.relation||"Contact")}</small></div><div class="record-value ${s>=0?'positive':'negative'}">${money(Math.abs(s))}<small>${s>=0?'To receive':'To pay'}</small></div></div>`}).join('');openModal("People",`<div class="workspace-hero"><div class="workspace-icon">👥</div><div><div class="eyebrow">PEOPLE & BALANCES</div><h3>Your contacts</h3><p>Save name and mobile number so every Lena/Dena report stays connected to the right person.</p></div></div><div class="mini-stat-grid"><div><b>${p.length}</b><small>People saved</small></div><div><b>${money(ledgerSummary().receive)}</b><small>Total to receive</small></div></div><button class="primary full" onclick="openPersonForm()">＋ ADD PERSON</button><div class="workspace-list people-list">${rows||`<div class="empty-state large"><span>👥</span><b>No people yet</b><p>Add your first contact with name and mobile number.</p></div>`}</div>`)}
function personBalance(name){let b=0;state.data.ledger.filter(x=>x.person===name).forEach(x=>{const a=Number(x.amount||0);if(["receive","lena"].includes(x.direction))b+=a;if(["pay","dena"].includes(x.direction))b-=a;if(x.direction==="received")b-=a;if(x.direction==="paid")b+=a});return b}
function openPersonForm(){openModal("Add Person",`<form id="personForm" class="professional-form"><div class="form-fields"><label class="field"><span>Person Name</span><div class="field-control"><input name="name" required placeholder="Full name"></div></label><label class="field"><span>Mobile Number</span><div class="field-control"><input name="phone" inputmode="numeric" maxlength="10" pattern="[6-9][0-9]{9}" required placeholder="10 digit mobile"></div></label><label class="field"><span>Relation</span><div class="field-control"><select name="relation"><option>Friend</option><option>Family</option><option>Colleague</option><option>Customer</option><option>Other</option></select></div></label></div><div class="form-footer"><button class="primary full">SAVE PERSON</button></div></form>`);$("#personForm").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),o={id:uid(),name:fd.get("name"),phone:fd.get("phone"),relation:fd.get("relation")};state.data.people.push(o);save();closeModal();openPeople();toast("Person saved")}}
function openLedger(){const l=ledgerSummary(),rows=state.data.ledger.map(x=>`<div class="record-card"><div class="record-icon">${["receive","lena","received"].includes(x.direction)?'🟢':'🔴'}</div><div class="record-main"><b>${esc(x.person||"Person")}</b><small>${esc(x.directionLabel||x.direction||"Entry")} · ${esc(x.date||"")} · ${esc(x.mode||"")}</small></div><div class="record-value">${money(x.amount||0)}<small>${esc(x.description||"")}</small></div></div>`).join('');openModal("Lena / Dena Ledger",`<div class="ledger-summary"><div><span>🟢</span><b>${money(l.receive)}</b><small>To Receive</small></div><div><span>🔴</span><b>${money(l.pay)}</b><small>To Pay</small></div></div><button class="primary full" onclick="openLedgerForm()">＋ ADD LENA / DENA ENTRY</button><div class="workspace-list ledger-list">${rows||`<div class="empty-state large"><span>🤝</span><b>No entries yet</b><p>Add who gave, who owes, amount, date and payment mode.</p></div>`}</div>`)}
function openLedgerForm(){const names=state.data.people.map(x=>x.name);openModal("Add Lena / Dena",`<form id="ledgerForm" class="professional-form"><div class="form-fields"><label class="field"><span>Person</span><div class="field-control"><select name="person" required>${names.length?names.map(x=>`<option>${esc(x)}</option>`).join(""):"<option value=''>Add a person first</option>"}</select></div></label><label class="field"><span>Type</span><div class="field-control"><select name="direction" required><option value="lena">🟢 Lena — I will receive</option><option value="dena">🔴 Dena — I will pay</option><option value="received">✅ Received — payment came back</option><option value="paid">✅ Paid — I paid the person</option></select></div></label><label class="field"><span>Date</span><div class="field-control"><input name="date" type="date" required></div></label><label class="field"><span>Description</span><div class="field-control"><input name="description" placeholder="Why is this amount due?"></div></label><label class="field"><span>Amount (₹)</span><div class="field-control"><input name="amount" type="number" inputmode="decimal" min="0" step="0.01" required placeholder="Enter amount"></div></label><label class="field"><span>Payment Mode</span><div class="field-control"><select name="mode" required>${paymentOptions().map(x=>`<option>${x}</option>`).join("")}</select></div></label></div><div class="form-footer"><button class="primary full" ${names.length?'':'disabled'}>SAVE ENTRY</button></div></form>`);const d=$("#ledgerForm input[name='date']");if(d)d.value=new Date().toISOString().slice(0,10);$("#ledgerForm").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),dir=fd.get("direction"),labels={lena:"🟢 Lena — To Receive",dena:"🔴 Dena — To Pay",received:"✅ Received",paid:"✅ Paid"};state.data.ledger.push({id:uid(),person:fd.get("person"),direction:dir,directionLabel:labels[dir],date:fd.get("date"),description:fd.get("description"),amount:Number(fd.get("amount")),mode:fd.get("mode")});save();closeModal();openLedger();toast("Ledger updated")}}
function openBulk(){openModal("Bulk Data Import",`<div class="bulk-head"><div class="bulk-icon">📥</div><div><div class="eyebrow">OLD DATA → ABS</div><h3>Import previous records</h3><p>Paste CSV rows or upload a CSV file. Minimum columns: Date, Type, Description, Amount.</p></div></div><div class="bulk-template"><b>CSV format</b><code>Date,Type,Category,Description,Amount,Payment Mode,Person Name,Person Number,Ledger Direction</code><small>Type: Income / Expense / Ledger · Payment: UPI / Cash / Bank Transfer / Card / Cheque / Other · Ledger Direction: Lena / Dena / Received / Paid</small></div><label class="field"><span>Upload CSV</span><div class="field-control"><input id="bulkFile" type="file" accept=".csv,text/csv"></div></label><label class="field"><span>Or paste bulk rows</span><div class="field-control"><textarea id="bulkText" rows="8" placeholder="Date,Type,Category,Description,Amount,Payment Mode,Person Name,Person Number,Ledger Direction\n01-09-2026,Income,Salary,Monthly salary,19000,Bank Transfer,,,\n02-09-2026,Expense,Food & Dining,Lunch,250,UPI,,,\n03-09-2026,Ledger,,Rahul lent me money,1000,Cash,Rahul,9876543210,Lena"></textarea></div></label><div class="bulk-actions"><button class="ghost" onclick="downloadBulkTemplate()">⇩ TEMPLATE</button><button class="primary" onclick="processBulkImport()">IMPORT DATA</button></div><div class="bulk-note">✓ Existing records are kept. Imported records are added to them.</div>`);$("#bulkFile").onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>$("#bulkText").value=r.result;r.readAsText(f)}}
function parseCSV(text){const rows=[];let row=[],cell="",q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++;continue}if(c==='"'){q=!q;continue}if(c===','&&!q){row.push(cell.trim());cell="";continue}if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell.trim());if(row.some(x=>x!==""))rows.push(row);row=[];cell="";continue}cell+=c}if(cell!==""||row.length){row.push(cell.trim());if(row.some(x=>x!==""))rows.push(row)}return rows}
function processBulkImport(){const text=$("#bulkText").value.trim();if(!text)return toast("Paste CSV data first");const rows=parseCSV(text);if(rows.length<2)return toast("CSV needs a header and at least one row");const h=rows[0].map(x=>x.toLowerCase().replace(/\s+/g," ")),idx=k=>h.indexOf(k);const get=(r,...keys)=>{for(const k of keys){const i=idx(k);if(i>=0)return r[i]||""}return""};let added=0,skipped=0;rows.slice(1).forEach(r=>{const type=get(r,"type").toLowerCase();const amount=Number(String(get(r,"amount")).replace(/[^0-9.-]/g,""));const date=normalizeDate(get(r,"date"));const desc=get(r,"description");if(!amount||!date||!type){skipped++;return}const mode=get(r,"payment mode","mode")||"Other",category=get(r,"category")||"Other",name=get(r,"person name","person","name"),phone=get(r,"person number","phone","mobile"),dir=get(r,"ledger direction","direction").toLowerCase();if(type==="income"){state.data.income.push({id:uid(),date,source:category||"Other",description:desc,amount,mode});added++}else if(type==="expense"){state.data.expenses.push({id:uid(),date,category,description:desc,amount,mode});added++}else if(type==="ledger"){if(name&&!state.data.people.some(p=>p.name===name)){state.data.people.push({id:uid(),name,phone,relation:"Contact"})}const d=["lena","dena","received","paid"].includes(dir)?dir:"lena";state.data.ledger.push({id:uid(),person:name||"Unknown",direction:d,directionLabel:d==="lena"?"🟢 Lena — To Receive":d==="dena"?"🔴 Dena — To Pay":d==="received"?"✅ Received":"✅ Paid",date,description:desc,amount,mode});added++}else{skipped++}});save();closeModal();render();toast(`${added} imported · ${skipped} skipped`) }
function downloadBulkTemplate(){const csv=`Date,Type,Category,Description,Amount,Payment Mode,Person Name,Person Number,Ledger Direction\n01-09-2026,Income,Salary,Monthly salary,19000,Bank Transfer,,,\n02-09-2026,Expense,Food & Dining,Lunch,250,UPI,,,\n03-09-2026,Ledger,,Rahul lent me money,1000,Cash,Rahul,9876543210,Lena`;const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="ABS-DASHBOARD-bulk-template.csv";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function openCategories(){ensureData();const exp=state.data.settings.categories||[],inc=state.data.settings.incomeCategories||[];openModal("Categories",`<div class="category-manager"><div class="category-intro"><div class="workspace-icon">🗂</div><div><div class="eyebrow">PERSONAL CATEGORIES</div><h3>Make ABS fit your life</h3><p>Add categories that are specific to you. They will appear automatically in the relevant forms.</p></div></div><div class="cat-section"><h4>Expense Categories</h4><div class="chip-list">${exp.map((x,i)=>`<span class="cat-chip">${esc(x)} ${i>=12?`<button onclick="removeCategory('expense',${i})">×</button>`:""}</span>`).join('')}</div><form class="inline-add" onsubmit="addCategory(event,'expense')"><input id="newExpenseCat" placeholder="e.g. Drinks, Gym, Fuel" required><button class="primary">+ ADD</button></form></div><div class="cat-section"><h4>Income Categories</h4><div class="chip-list">${inc.map((x,i)=>`<span class="cat-chip">${esc(x)} ${i>=7?`<button onclick="removeCategory('income',${i})">×</button>`:""}</span>`).join('')}</div><form class="inline-add" onsubmit="addCategory(event,'income')"><input id="newIncomeCat" placeholder="e.g. Rental, Commission" required><button class="primary">+ ADD</button></form></div></div>`)}
function addCategory(e,type){e.preventDefault();ensureData();const id=type==='expense'?'newExpenseCat':'newIncomeCat',v=$("#"+id).value.trim();if(!v)return;if(v.length>40)return toast("Category name is too long");const arr=type==='expense'?state.data.settings.categories:state.data.settings.incomeCategories;if(arr.some(x=>x.toLowerCase()===v.toLowerCase()))return toast("Category already exists");arr.push(v);save();openCategories();toast("Category added")}
function removeCategory(type,i){ensureData();const arr=type==='expense'?state.data.settings.categories:state.data.settings.incomeCategories;if(i< (type==='expense'?12:7))return toast("Default category cannot be removed");arr.splice(i,1);save();openCategories();toast("Category removed")}
function allHistory(){return[...state.data.income.map(x=>({...x,_kind:'income',_label:x.source||'Income',_desc:x.description||x.source||''})),...state.data.expenses.map(x=>({...x,_kind:'expense',_label:x.category||'Expense',_desc:x.description||x.category||''})),...state.data.ledger.map(x=>({...x,_kind:'ledger',_label:x.directionLabel||x.direction,_desc:`${x.person||'Person'} · ${x.description||''}`}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function openHistory(){const rows=allHistory();openModal("History",`<div class="history-head"><div><div class="eyebrow">ALL RECORDS</div><h3>Income · Expense · Ledger</h3><p>View your complete financial history. Use Edit Records when you need to correct an entry.</p></div><div class="history-count">${rows.length}<small>ENTRIES</small></div></div><div class="history-list">${rows.map(x=>`<div class="history-row"><div class="history-icon ${x._kind}">${x._kind==='income'?'↗':x._kind==='expense'?'↘':'🤝'}</div><div class="history-main"><b>${esc(x._label)}</b><small>${esc(x.date||'')} · ${esc(x.mode||'')} · ${esc(x._desc)}</small></div><strong>${money(x.amount)}</strong></div>`).join('')||`<div class="empty-state large"><span>🕘</span><b>No history yet</b><p>Your saved income, expenses and ledger entries will appear here.</p></div>`}</div>`)}
function openEditRecords(){const rows=allHistory();openModal("Edit Records",`<div class="history-head"><div><div class="eyebrow">RECORD CORRECTION</div><h3>Edit saved entries</h3><p>Choose an entry below to correct its date, category, description, amount or payment mode.</p></div><div class="history-count">${rows.length}<small>EDITABLE</small></div></div><div class="history-list">${rows.map(x=>`<div class="history-row edit-row"><div class="history-icon ${x._kind}">${x._kind==='income'?'↗':x._kind==='expense'?'↘':'🤝'}</div><div class="history-main"><b>${esc(x._label)}</b><small>${esc(x.date||'')} · ${esc(x.mode||'')} · ${esc(x._desc)}</small></div><strong>${money(x.amount)}</strong><button class="mini-edit" onclick="editHistoryEntry('${x._kind}',${x.id})">Edit</button></div>`).join('')||`<div class="empty-state large"><span>✎</span><b>No records to edit</b><p>Add an income, expense or ledger entry first.</p></div>`}</div>`)}
function editHistoryEntry(kind,id){const arr=state.data[kind==='income'?'income':kind==='expense'?'expenses':'ledger'];const x=arr.find(v=>String(v.id)===String(id));if(!x)return toast("Record not found");if(kind==='ledger'){const names=state.data.people.map(p=>p.name);openModal("Edit Ledger Entry",`<form id="editHistoryForm" class="professional-form"><div class="form-fields"><label class="field"><span>Person</span><div class="field-control"><select name="person">${names.map(n=>`<option ${n===x.person?'selected':''}>${esc(n)}</option>`).join('')}</select></div></label><label class="field"><span>Type</span><div class="field-control"><select name="direction"><option value="lena" ${x.direction==='lena'?'selected':''}>🟢 Lena — I will receive</option><option value="dena" ${x.direction==='dena'?'selected':''}>🔴 Dena — I will pay</option><option value="received" ${x.direction==='received'?'selected':''}>✅ Received</option><option value="paid" ${x.direction==='paid'?'selected':''}>✅ Paid</option></select></div></label><label class="field"><span>Date</span><div class="field-control"><input name="date" type="date" value="${esc(x.date||'')}"></div></label><label class="field"><span>Description</span><div class="field-control"><input name="description" value="${esc(x.description||'')}"></div></label><label class="field"><span>Amount</span><div class="field-control"><input name="amount" type="number" min="0" step="0.01" value="${Number(x.amount||0)}"></div></label><label class="field"><span>Payment Mode</span><div class="field-control"><select name="mode">${paymentOptions().map(m=>`<option ${m===x.mode?'selected':''}>${m}</option>`).join('')}</select></div></label></div><button class="primary full">SAVE CHANGES</button></form>`)}else{const fields=kind==='income'?[['date','Date','date'],['source','Income Type','select'],['description','Description','text'],['amount','Amount','number'],['mode','Payment Mode','select']]:[['date','Date','date'],['category','Category','select'],['description','Description','text'],['amount','Amount','number'],['mode','Payment Mode','select']];openModal(`Edit ${kind==='income'?'Income':'Expense'}`,`<form id="editHistoryForm" class="professional-form"><div class="form-fields">${fields.map(f=>{const opts=f[0]==='source'?incomeCategories():f[0]==='category'?expenseCategories():paymentOptions();return`<label class="field"><span>${f[1]}</span><div class="field-control">${f[2]==='select'?`<select name="${f[0]}">${opts.map(o=>`<option ${o===x[f[0]]?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="${f[0]}" type="${f[2]}" value="${esc(x[f[0]]??'')}" ${f[0]==='amount'?'min="0" step="0.01"':''}>`}</div></label>`}).join('')}</div><button class="primary full">SAVE CHANGES</button></form>`)}$("#editHistoryForm").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);fd.forEach((v,k)=>x[k]=k==='amount'?Number(v):v);if(kind==='ledger'){const labels={lena:'🟢 Lena — To Receive',dena:'🔴 Dena — To Pay',received:'✅ Received',paid:'✅ Paid'};x.directionLabel=labels[x.direction]}save();openHistory();toast("Entry updated")}}

function statementRows(){return[...state.data.income.map(x=>({...x,_kind:'income',_label:x.source||'Income',_desc:x.description||x.source||'Income',_credit:Number(x.amount||0),_debit:0})),...state.data.expenses.map(x=>({...x,_kind:'expense',_label:x.category||'Expense',_desc:x.description||x.category||'Expense',_credit:0,_debit:Number(x.amount||0)})),...state.data.emi.map(x=>({...x,_kind:'emi',_label:x.name||x.loan||'EMI',_desc:x.remarks||x.loan||'EMI payment',_credit:0,_debit:Number(x.amount||0)})),...state.data.ledger.map(x=>{const d=x.direction;return {...x,_kind:'ledger',_label:x.directionLabel||d||'Ledger',_desc:`${x.person||'Person'} · ${x.description||''}`,_credit:['lena','receive','received'].includes(d)?Number(x.amount||0):0,_debit:['dena','pay','paid'].includes(d)?Number(x.amount||0):0}})].filter(x=>x.date).sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function statementDateRange(filter,from,to){const end=new Date();end.setHours(23,59,59,999);let start=new Date(0);if(filter==='today'){start=new Date();start.setHours(0,0,0,0)}else if(filter==='7d'){start=new Date(end);start.setDate(start.getDate()-6);start.setHours(0,0,0,0)}else if(filter==='1m'){start=new Date(end);start.setMonth(start.getMonth()-1);start.setDate(start.getDate()+1);start.setHours(0,0,0,0)}else if(filter==='6m'){start=new Date(end);start.setMonth(start.getMonth()-6);start.setDate(start.getDate()+1);start.setHours(0,0,0,0)}else if(filter==='custom'){start=new Date(from||end);start.setHours(0,0,0,0);end.setTime(new Date(to||from||end).getTime());end.setHours(23,59,59,999)}return{start,end}}
function filteredStatementRows(filter='all',from='',to=''){const rows=statementRows();if(filter==='all')return rows;const r=statementDateRange(filter,from,to);return rows.filter(x=>{const d=new Date(x.date+'T12:00:00');return !isNaN(d)&&d>=r.start&&d<=r.end})}
function openStatement(){
 const today=new Date().toISOString().slice(0,10);
 openModal('ABS Statement',`<div class="statement-dashboard"><div class="statement-hero"><div><div class="eyebrow">ABS DASHBOARD</div><h3>Statement Center</h3><p>Review your real transactions by period. Nothing is estimated.</p></div><div class="statement-hero-icon"><img src="assets/abs-logo.png" alt="ABS" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span>ABS</span></div></div><div class="statement-period-label">SELECT PERIOD</div><div class="statement-filters"><button class="statement-filter active" data-filter="all">All</button><button class="statement-filter" data-filter="date">Date</button><button class="statement-filter" data-filter="7d">7 Days</button><button class="statement-filter" data-filter="1m">1 Month</button><button class="statement-filter" data-filter="6m">6 Months</button><button class="statement-filter" data-filter="custom">Custom</button></div><div id="statementCustom" class="statement-custom hidden"><label>From<input id="statementFrom" type="date" value="${today}"></label><label>To<input id="statementTo" type="date" value="${today}"></label></div><div id="statementSummary" class="statement-summary"></div><div class="statement-list-head"><div><b>Transactions</b><small id="statementRangeText">All recorded activity</small></div><span>Latest first</span></div><div id="statementList" class="statement-list"></div><button id="statementPDF" class="primary full statement-pdf-btn">DOWNLOAD PREMIUM PDF</button></div>`);
 const update=()=>{const active=document.querySelector('.statement-filter.active')?.dataset.filter||'all';const from=$("#statementFrom")?.value||'',to=$("#statementTo")?.value||'';if((active==='custom'||active==='date')&&from&&to&&from>to){toast('From date cannot be after To date');return}const rows=filteredStatementRows(active,from,to);const income=rows.reduce((s,x)=>s+x._credit,0),debit=rows.reduce((s,x)=>s+x._debit,0),net=income-debit;const labels={all:'All recorded activity',date:`Date · ${from||'—'}`,'7d':'Last 7 days','1m':'Last 1 month','6m':'Last 6 months',custom:`${from||'—'} to ${to||from||'—'}`};$("#statementRangeText").textContent=labels[active];$("#statementSummary").innerHTML=`<div class="statement-summary-card"><small>RECORDS</small><b>${rows.length}</b><span>transactions</span></div><div class="statement-summary-card credit"><small>MONEY IN</small><b>${money(income)}</b><span>credit</span></div><div class="statement-summary-card debit"><small>MONEY OUT</small><b>${money(debit)}</b><span>debit</span></div><div class="statement-summary-card ${net>=0?'net-good':'net-bad'}"><small>NET</small><b>${money(net)}</b><span>period result</span></div>`;$("#statementList").innerHTML=rows.map((x,i)=>`<div class="statement-row statement-row-animated" style="animation-delay:${Math.min(i,15)*25}ms"><div class="statement-date"><b>${esc(x.date||'—')}</b><span>${esc(x._kind||'')}</span></div><div class="statement-main"><b>${esc(x._label)}</b><small>${esc(x._desc)}${x.mode?' · '+esc(x.mode):''}</small></div><strong class="${x._credit?'positive':'negative'}">${x._credit?'+':'−'}${money(x._credit||x._debit)}</strong></div>`).join('')||`<div class="statement-empty"><span>▤</span><b>No records in this period</b><p>Choose another period or add a transaction.</p></div>`;$("#statementPDF").onclick=()=>exportStatementPDF(active,from,to)};
 document.querySelectorAll('.statement-filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.statement-filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');$("#statementCustom").classList.toggle('hidden',!['date','custom'].includes(b.dataset.filter));$("#statementTo").parentElement.classList.toggle('hidden',b.dataset.filter==='date');update()});
 $("#statementFrom")?.addEventListener('change',update);$("#statementTo")?.addEventListener('change',update);update();
}function exportStatementPDF(filter='all',from='',to=''){
 if(!window.jspdf?.jsPDF)return toast('PDF engine is loading — try again');
 const rows=filteredStatementRows(filter,from,to),{jsPDF}=window.jspdf,doc=new jsPDF({unit:'pt',format:'a4'}),W=595,H=842,M=34;
 const fmt=n=>'INR '+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2});
 const title=filter==='all'?'All recorded activity':filter==='date'?`Date · ${from||'—'}`:filter==='7d'?'Last 7 days':filter==='1m'?'Last 1 month':filter==='6m'?'Last 6 months':`${from||'—'} to ${to||from||'—'}`;
 const ink=[17,25,39],muted=[101,113,132],accent=[91,82,220],green=[12,154,111],red=[220,72,96],soft=[245,247,251],soft2=[235,239,247];let page=1,y=0;
 function header(){doc.setFillColor(...ink);
doc.rect(0,0,W,104,'F');
doc.setFillColor(...accent);
doc.roundedRect(M,22,52,52,13,13,'F');

try{
    doc.addImage(logo,"PNG",M+4,26,44,44);
}catch(e){}

doc.setFontSize(23);doc.text('ABS STATEMENT',M+68,48);doc.setFont('helvetica','normal');doc.setFontSize(8.5);doc.text('PREMIUM PERSONAL FINANCE REPORT',M+69,65);doc.setTextColor(...ink);doc.setFontSize(9);doc.text(`Account  ·  ${String(state.user?.name||'User')}`,M,125);doc.text(`Period  ·  ${title}`,W-M,125,{align:'right'});doc.setTextColor(...muted);doc.text(`Generated  ·  ${new Date().toLocaleString('en-IN')}`,M,139)}
 function footer(){doc.setDrawColor(224,228,236);doc.line(M,H-42,W-M,H-42);doc.setTextColor(...muted);doc.setFontSize(7.5);doc.text('ABS DASHBOARD  ·  Confidential personal finance statement',M,H-27);doc.text(`Page ${page}`,W-M,H-27,{align:'right'})}
 function card(x,label,value,color){doc.setFillColor(...soft);doc.roundedRect(x,y,166,66,12,12,'F');doc.setTextColor(...muted);doc.setFont('helvetica','bold');doc.setFontSize(7.5);doc.text(label.toUpperCase(),x+13,y+19);doc.setTextColor(...color);doc.setFontSize(14);doc.text(fmt(value),x+13,y+45)}
 function tableHead(){doc.setFillColor(...ink);doc.roundedRect(M,y,W-2*M,29,7,7,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(7.5);doc.text('DATE',M+9,y+19);doc.text('TYPE',M+77,y+19);doc.text('DESCRIPTION',M+135,y+19);doc.text('MODE',M+343,y+19);doc.text('AMOUNT',W-M-9,y+19,{align:'right'});y+=29}
 const credit=rows.reduce((s,x)=>s+x._credit,0),debit=rows.reduce((s,x)=>s+x._debit,0),net=credit-debit;
 header();y=162;doc.setFont('helvetica','bold');doc.setFontSize(12);doc.setTextColor(...ink);doc.text('ACCOUNT SUMMARY',M,y);y+=12;card(M,'Money In',credit,green);card(M+181,'Money Out',debit,red);card(M+362,'Net',net,net>=0?green:red);y+=83;
 doc.setFillColor(...soft2);doc.roundedRect(M,y,W-2*M,42,10,10,'F');doc.setTextColor(...muted);doc.setFont('helvetica','bold');doc.setFontSize(7);doc.text('STATEMENT OVERVIEW',M+13,y+15);doc.setTextColor(...ink);doc.setFont('helvetica','normal');doc.setFontSize(8.5);doc.text(`${rows.length} transaction(s) included  ·  Money In ${fmt(credit)}  ·  Money Out ${fmt(debit)}`,M+13,y+30);y+=62;
 doc.setTextColor(...ink);doc.setFont('helvetica','bold');doc.setFontSize(12);doc.text('TRANSACTION DETAIL',M,y);y+=14;tableHead();
 rows.forEach((x,i)=>{if(y>H-70){footer();doc.addPage();page++;header();y=162;doc.setFont('helvetica','bold');doc.setFontSize(11);doc.setTextColor(...ink);doc.text('TRANSACTION DETAIL · CONTINUED',M,y);y+=14;tableHead()}doc.setFillColor(...(i%2?[255,255,255]:[248,249,252]));doc.rect(M,y,W-2*M,23,'F');doc.setTextColor(...ink);doc.setFont('helvetica','normal');doc.setFontSize(7.2);doc.text(String(x.date||'—').slice(0,10),M+9,y+15);doc.text(String(x._kind||'').toUpperCase().slice(0,9),M+77,y+15);doc.text(String(x._desc||x._label||'').slice(0,34),M+135,y+15);doc.text(String(x.mode||'—').slice(0,16),M+343,y+15);doc.setFont('helvetica','bold');doc.setTextColor(...(x._credit?green:red));doc.text((x._credit?'+ ':'- ')+fmt(x._credit||x._debit),W-M-9,y+15,{align:'right'});y+=23});
 if(!rows.length){doc.setTextColor(...muted);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text('No transactions found for the selected period.',M+10,y+20);y+=30}
 if(y>H-120){footer();doc.addPage();page++;header();y=162}y+=14;doc.setFillColor(...ink);doc.roundedRect(M,y,W-2*M,68,12,12,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(9);doc.text('STATEMENT TOTALS',M+14,y+20);doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(`Money In  ${fmt(credit)}    ·    Money Out  ${fmt(debit)}    ·    Net  ${fmt(net)}`,M+14,y+38);doc.text(`${rows.length} record(s) included for ${title}.`,M+14,y+53);footer();doc.save(`ABS-Statement-${filter}-${new Date().toISOString().slice(0,10)}.pdf`)
}
function renderAds(){const ads=JSON.parse(localStorage.getItem("abs_ads")||"[]").filter(x=>x.active!==false);if(!ads.length)return"";const id="ad_"+Date.now();setTimeout(()=>{const el=document.getElementById(id);if(!el)return;const slides=[...el.querySelectorAll(".ad-slide")],dots=[...el.querySelectorAll(".ad-dot")];let i=0;const show=()=>{slides.forEach((c,n)=>c.classList.toggle("active",n===i));dots.forEach((d,n)=>d.classList.toggle("active",n===i));el.dataset.index=i};show();if(slides.length>1){el.querySelector(".ad-prev")?.addEventListener("click",e=>{e.preventDefault();i=(i-1+slides.length)%slides.length;show()});el.querySelector(".ad-next")?.addEventListener("click",e=>{e.preventDefault();i=(i+1)%slides.length;show()});dots.forEach((d,n)=>d.addEventListener("click",e=>{e.preventDefault();i=n;show()}));setInterval(()=>{if(!document.hidden){i=(i+1)%slides.length;show()}},4500)}},0);return`<section class="ad-banner" id="${id}" aria-label="Advertisement slider"><div class="ad-track">${ads.map((a,i)=>`<a class="ad-slide ${i===0?'active':''}" href="${esc(a.link||'#')}" target="_blank" rel="noopener"><div class="ad-copy"><span>${esc(a.badge||'FEATURED')}</span><b>${esc(a.title||'ABS DASHBOARD')}</b><small>${esc(a.text||'')}</small></div>${a.image?`<img src="${esc(a.image)}" alt="${esc(a.title||'Advertisement')}">`:''}</a>`).join('')}</div>${ads.length>1?`<button class="ad-prev" aria-label="Previous banner">‹</button><button class="ad-next" aria-label="Next banner">›</button><div class="ad-dots">${ads.map((_,i)=>`<button class="ad-dot ${i===0?'active':''}" aria-label="Banner ${i+1}"></button>`).join('')}</div>`:''}</section>`}
const AI_FLOW={
 'Account & Balance':{icon:'◈',desc:'Your money at a glance',qs:['What is my available balance?','How much income do I have?','What are my total savings?','How much do I need to receive?']},
 'Spending':{icon:'↘',desc:'Understand where your money goes',qs:['How much have I spent?','Which expense category is highest?','Show my recent expenses.','What is my average monthly expense?']},
 'Loans & EMI':{icon:'▣',desc:'Track loans and repayments',qs:['How many loans do I have?','What is my total loan principal?','Show my EMI payments.','How much EMI have I paid?']},
 'Lena / Dena':{icon:'⇄',desc:'Money to receive and pay',qs:['How much do I need to receive?','How much do I need to pay?','Show my Lena / Dena activity.']},
 'App Services':{icon:'✦',desc:'Get help using ABS Dashboard',qs:['How do I add an expense?','How do I add income?','How do I import old data?','How do I download my statement?','How do I change my password?','What is Premium?','How do I request Premium?','How do I edit my profile?']}
};
const AI_HOME=[
 {key:'monthExpense',icon:'↘',title:'This Month Expense',desc:'See how much you spent this month.'},
 {key:'monthIncome',icon:'↗',title:'This Month Income',desc:'Check income recorded this month.'},
 {key:'monthSaving',icon:'◌',title:'This Month Saving',desc:'Know your actual monthly saving.'},
 {key:'balance',icon:'◈',title:'Available Balance',desc:'See your current usable balance.'},
 {key:'loans',icon:'▣',title:'Loans & EMI',desc:'Review loans and EMI payments.'}
];
function currentMonthTotals(){const now=new Date(),ym=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;const sum=arr=>(arr||[]).filter(x=>normalizeDate(x.date||x.createdAt).slice(0,7)===ym).reduce((a,x)=>a+Number(x.amount||0),0);const income=sum(state.data.income),expense=sum(state.data.expenses),emi=sum(state.data.emi);return{income,expense,emi,saving:income-expense-emi,label:now.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}}
function aiAnswerText(q){const t=totals(),l=ledgerSummary(),m=currentMonthTotals();if(q==='__monthExpense')return`In ${m.label}, your recorded expenses are ${money(m.expense)}. I checked your saved expense records for this month.`;if(q==='__monthIncome')return`In ${m.label}, your recorded income is ${money(m.income)}. This uses only income entries saved in ABS Dashboard.`;if(q==='__monthSaving')return`Your ${m.label} saving is ${money(m.saving)}. It is calculated as income − expenses − EMI for this month.`;if(q==='__balance')return`Your current available balance is ${money(Number(t.net||0)+Number(l.receive||0)-Number(l.pay||0))}. I calculated it from your saved income, expenses, EMI and Lena / Dena balances.`;if(q==='__loans')return`You have ${state.data.loans.length} recorded loan(s), with ${money(t.loan)} total principal. Recorded EMI payments are ${money(t.emi)}.`;if(q==='What is my available balance?')return`Your available balance is ${money(Number(t.net||0)+Number(l.receive||0)-Number(l.pay||0))}.`;if(q==='How much income do I have?')return`You have recorded ${money(t.income)} as total income.`;if(q==='What are my total savings?')return`Your current net savings are ${money(t.net)}.`;if(q==='How much have I spent?')return`Your recorded expenses total ${money(t.expense)}.`;if(q==='Which expense category is highest?'){const m2={};state.data.expenses.forEach(x=>m2[x.category||'Other']=(m2[x.category||'Other']||0)+Number(x.amount||0));const top=Object.entries(m2).sort((a,b)=>b[1]-a[1])[0];return top?`${top[0]} is your highest recorded expense category at ${money(top[1])}.`:'You have no expense records yet.'}if(q==='Show my recent expenses.')return state.data.expenses.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,5).map(x=>`${x.category||'Expense'} — ${money(x.amount)}${x.date?' · '+x.date:''}`).join('\n')||'You have no expense records yet.';if(q==='What is my average monthly expense?'){const vals={};state.data.expenses.forEach(x=>{const d=normalizeDate(x.date||x.createdAt);if(d)vals[d.slice(0,7)]=(vals[d.slice(0,7)]||0)+Number(x.amount||0)});const a=Object.values(vals);return a.length?`Your average recorded monthly expense is ${money(a.reduce((x,y)=>x+y,0)/a.length)} across ${a.length} month(s).`:'You do not have enough expense history yet.'}if(q==='How many loans do I have?')return`You have ${state.data.loans.length} recorded loan(s).`;if(q==='What is my total loan principal?')return`Your recorded loan principal is ${money(t.loan)}.`;if(q==='Show my EMI payments.')return state.data.emi.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,6).map(x=>`${x.name||x.loan||'EMI'} — ${money(x.amount)}${x.date?' · '+x.date:''}`).join('\n')||'No EMI payments recorded yet.';if(q==='How much EMI have I paid?')return`Your total recorded EMI payments are ${money(t.emi)}.`;if(q==='How much do I need to receive?')return`You currently have ${money(l.receive)} marked as money to receive.`;if(q==='How much do I need to pay?')return`You currently have ${money(l.pay)} marked as money to pay.`;if(q==='Show my Lena / Dena activity.')return state.data.ledger.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,8).map(x=>`${x.person||'Person'} — ${x.directionLabel||x.direction} — ${money(x.amount)}`).join('\n')||'No Lena / Dena entries recorded yet.';if(q==='How do I add an expense?')return'Open Explore → Add Expense, enter amount, category, date and payment mode, then save.';if(q==='How do I add income?')return'Open Explore → Add Income, enter amount, source, date and payment mode, then save.';if(q==='How do I import old data?')return'Open Explore → Bulk Data and import your previous records using the provided format.';if(q==='How do I download my statement?')return'Open Explore → Statement, choose your period, then download the selected statement as PDF.';if(q==='How do I change my password?')return'Open Profile → Change Password, enter your current password and set a new password.';if(q==='What is Premium?')return'Premium is the verified ABS Dashboard account status. When Admin approves your Premium request, the verified blue badge appears on your profile and Premium is unlocked.';if(q==='How do I request Premium?')return'Open Profile → ABS Premium → Request Premium. Your request goes to ABS Admin for review. Until it is approved or rejected, you cannot submit another request.';if(q==='How do I edit my profile?')return'Open Profile → Edit Profile to update your name or mobile number.';if(q==='How do I use the app?')return'Use Dashboard for your financial overview, Explore to add records and reports, ABS AI for answers, and Profile for account settings.';return'I can help with your ABS Dashboard data, reports, loans, spending and app services.'}
function aiTopicAnswer(){return'I checked your saved ABS Dashboard records. Choose a question below and I’ll calculate the answer from your actual data.'}
function aiNextOptions(q){if(AI_FLOW[q])return AI_FLOW[q].qs.slice(0,3);for(const x of Object.values(AI_FLOW))if(x.qs.includes(q))return x.qs.filter(v=>v!==q).slice(0,3);return AI_FLOW['Account & Balance'].qs.slice(0,3)}
function aiFreeText(text){const q=text.trim().toLowerCase();if(!q)return "Please type a question.";if(q.includes("expense")||q.includes("spent"))return aiAnswerText(q.includes("this month")?"__monthExpense":"How much have I spent?");if(q.includes("income")||q.includes("earning"))return aiAnswerText(q.includes("this month")?"__monthIncome":"How much income do I have?");if(q.includes("saving"))return aiAnswerText(q.includes("this month")?"__monthSaving":"What are my total savings?");if(q.includes("balance")||q.includes("available"))return aiAnswerText("__balance");if(q.includes("loan"))return aiAnswerText("__loans");if(q.includes("emi"))return aiAnswerText("How much EMI have I paid?");if(q.includes("receive")||q.includes("lena"))return aiAnswerText("How much do I need to receive?");if(q.includes("pay")||q.includes("dena"))return aiAnswerText("How much do I need to pay?");if(q.includes("statement"))return aiAnswerText("How do I download my statement?");if(q.includes("add expense"))return aiAnswerText("How do I add an expense?");if(q.includes("add income"))return aiAnswerText("How do I add income?");return "I checked your saved ABS Dashboard data. Try asking about this month's expense, income, saving, balance, loans, EMI, Lena / Dena or statement."}
function renderAI(){document.body.classList.add('ai-open');state.aiHistory=state.aiHistory||[];const history=state.aiHistory;const monthLabel=currentMonthTotals().label;const homeButtons=AI_HOME.map(x=>`<button type="button" class="ai-home-option" data-ai-key="${x.key}"><span class="ai-option-icon">${x.icon}</span><span><b>${esc(x.title)}</b><small>${esc(x.desc)}</small></span><i>›</i></button>`).join('');const moreButtons=Object.entries(AI_FLOW).map(([name,v])=>`<button type="button" class="ai-more-option" data-ai-topic="${escAttr(name)}"><span class="ai-option-icon">${v.icon}</span><span><b>${esc(name)}</b><small>${esc(v.desc)}</small></span><i>›</i></button>`).join('');const historyHtml=history.map(m=>`<div class="ai-chat-row user-row"><div class="ai-user-bubble"><span>${esc(m.qTitle||m.q)}</span><time>${esc(m.time||'')}</time></div></div><div class="ai-chat-row bot-row"><div class="ai-bot-bubble"><div class="ai-bot-head"><span class="ai-bot-orb">✦</span><div><b>ABS AI</b><small>Verified account analysis</small></div></div><p>${esc(m.a).replace(/\n/g,'<br>')}</p><time>${esc(m.time||'')}</time></div></div>`).join('');const follow=history.length?aiNextOptions(history[history.length-1].q).map(q=>`<button type="button" class="ai-suggest-btn" data-ai-question="${escAttr(q)}">${esc(q)} <span>›</span></button>`).join(''):'';const initial=`<section class="ai-home-panel"><div class="ai-home-brand"><div class="ai-home-orb">✦</div><div><div class="eyebrow">ABS DASHBOARD AI</div><h1>Personal Finance Copilot</h1><p>I analyse your saved account data and explain it simply.</p></div></div><div class="ai-section-title">QUICK INSIGHTS · ${esc(monthLabel)}</div><div class="ai-home-options">${homeButtons}</div><button type="button" class="ai-more-toggle" id="aiMoreBtn">＋ MORE SERVICES</button><div id="aiMorePanel" class="ai-more-panel hidden">${moreButtons}</div></section>`;const chat=historyHtml+(history.length?`<div class="ai-suggestions"><div class="ai-section-title">SUGGESTED NEXT</div>${follow}</div>`:'');const shell=`<div class="ai-fullscreen"><header class="ai-new-head"><button type="button" class="ai-close" id="aiBack">‹</button><div class="ai-brand-mark">✦</div><div class="ai-head-copy"><b>ABS AI</b><small>Personal Finance Copilot</small></div><button type="button" class="ai-reset" id="aiReset">↻</button></header><main class="ai-new-body">${initial}<section class="ai-chat-thread">${chat}</section><button type="button" class="ai-new-topic" id="aiNewTopic">＋ NEW TOPIC</button></main><div class="ai-chat-composer"><input id="aiChatInput" placeholder="Ask ABS AI anything about your finances..." autocomplete="off"><button type="button" id="aiSend">↑</button></div></div>`;$('#screen').innerHTML=shell;const ask=(q,title=q)=>{const now=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});state.aiHistory.push({q,a:aiAnswerText(q),qTitle:title,time:now});renderAI();setTimeout(()=>document.querySelector('.ai-chat-composer input')?.focus(),50)};document.getElementById('aiBack')?.addEventListener('click',()=>{state.tab='dashboard';render()});document.getElementById('aiReset')?.addEventListener('click',()=>{state.aiHistory=[];renderAI()});document.querySelectorAll('[data-ai-key]').forEach(b=>b.addEventListener('click',()=>{const item=AI_HOME.find(x=>x.key===b.dataset.aiKey);ask('__'+b.dataset.aiKey,item?.title||b.dataset.aiKey)}));document.querySelectorAll('[data-ai-topic]').forEach(b=>b.addEventListener('click',()=>{const topic=b.dataset.aiTopic;const now=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});state.aiHistory.push({q:topic,a:aiTopicAnswer(topic),qTitle:topic,time:now});renderAI()}));document.querySelectorAll('[data-ai-question]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.aiQuestion)));const more=document.getElementById('aiMoreBtn');more?.addEventListener('click',()=>document.getElementById('aiMorePanel')?.classList.toggle('hidden'));document.getElementById('aiNewTopic')?.addEventListener('click',()=>{state.aiHistory=[];renderAI()});const input=document.getElementById('aiChatInput'),send=document.getElementById('aiSend');const sendChat=()=>{const text=input?.value.trim();if(!text)return;const now=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});state.aiHistory.push({q:text,a:aiFreeText(text),qTitle:text,time:now});renderAI();setTimeout(()=>document.querySelector('.ai-chat-composer input')?.focus(),50)};send?.addEventListener('click',sendChat);input?.addEventListener('keydown',e=>{if(e.key==='Enter')sendChat()})}

async function exportPDF(){if(!window.jspdf?.jsPDF)return toast("PDF engine is loading — try again");const {jsPDF}=window.jspdf;
const doc=new jsPDF({unit:"pt",format:"a4"});
const logo=new Image();
logo.src="assets/abs-logo.png";

const t=totals(),l=ledgerSummary();const W=595,H=842,M=38;const ink=[18,24,39],muted=[102,112,128],accent=[67,56,202],soft=[244,246,250],green=[16,150,90],red=[210,60,70];const fmt=n=>"INR "+Number(n||0).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2});const short=s=>String(s??"").replace(/[\r\n]+/g," ").trim();let page=1;function header(){doc.setFillColor(...ink);doc.rect(0,0,W,88,"F");

doc.setFillColor(...accent);
doc.roundedRect(M,22,44,44,10,10,"F");

try{
    doc.addImage(logo,"PNG",M+2,24,40,40);
}catch(e){}

doc.setFontSize(22);doc.text("ABS STATEMENT",M+58,45);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text("PERSONAL FINANCE REPORT",M+59,61);doc.setTextColor(...ink);doc.setFontSize(10);doc.text(`Account: ${short(state.user?.name||"User")}`,M,108);doc.text(`Mobile: ${short(state.user?.mobile||"")}`,M,123);doc.text(`Generated: ${new Date().toLocaleString("en-IN")}`,W-M,108,{align:"right"});doc.text(`Period: All recorded activity`,W-M,123,{align:"right"})}function footer(){doc.setDrawColor(220,223,230);doc.line(M,H-42,W-M,H-42);doc.setTextColor(...muted);doc.setFontSize(8);doc.text("ABS DASHBOARD · Confidential personal finance statement",M,H-27);doc.text(`Page ${page}`,W-M,H-27,{align:"right"})}function newPage(){footer();doc.addPage();page++;header()}function card(x,y,w,h,label,value,color){doc.setFillColor(...soft);doc.roundedRect(x,y,w,h,10,10,"F");doc.setTextColor(...muted);doc.setFont("helvetica","bold");doc.setFontSize(8);doc.text(label.toUpperCase(),x+12,y+18);doc.setTextColor(...color);doc.setFontSize(14);doc.text(fmt(value),x+12,y+39)}header();let y=150;doc.setTextColor(...ink);doc.setFont("helvetica","bold");doc.setFontSize(12);doc.text("ACCOUNT OVERVIEW",M,y);y+=14;const gap=10,cw=(W-2*M-gap)/2;card(M,y,cw,54,"Total Income",t.income,green);card(M+cw+gap,y,cw,54,"Total Expenses",t.expense,red);y+=66;card(M,y,cw,54,"Net Savings",t.net,t.net>=0?green:red);card(M+cw+gap,y,cw,54,"EMI Paid",t.emi,accent);y+=66;card(M,y,cw,54,"To Receive",l.receive,green);card(M+cw+gap,y,cw,54,"To Pay",l.pay,red);y+=82;doc.setTextColor(...ink);doc.setFontSize(12);doc.text("MONEY MOVEMENT",M,y);y+=20;doc.setFillColor(...ink);doc.roundedRect(M,y,W-2*M,30,6,6,"F");doc.setTextColor(255,255,255);doc.setFontSize(8);doc.text("CATEGORY",M+12,y+19);doc.text("COUNT",M+230,y+19,{align:"right"});doc.text("AMOUNT",W-M-12,y+19,{align:"right"});y+=30;const overview=[["Income",state.data.income.length,t.income], ["Expenses",state.data.expenses.length,t.expense], ["Loan Principal",state.data.loans.length,t.loan], ["EMI Payments",state.data.emi.length,t.emi], ["Lena / Dena",state.data.ledger.length,state.data.ledger.reduce((s,x)=>s+Number(x.amount||0),0)]];overview.forEach((r,i)=>{if(i%2===0)doc.setFillColor(249,250,252);else doc.setFillColor(255,255,255);doc.rect(M,y,W-2*M,25,"F");doc.setTextColor(...ink);doc.setFont("helvetica","normal");doc.setFontSize(8.5);doc.text(r[0],M+12,y+16);doc.text(String(r[1]),M+230,y+16,{align:"right"});doc.setFont("helvetica","bold");doc.text(fmt(r[2]),W-M-12,y+16,{align:"right"});y+=25});y+=25;doc.setTextColor(...ink);doc.setFont("helvetica","bold");doc.setFontSize(12);doc.text("TRANSACTION DETAIL",M,y);y+=18;const rows=[...state.data.income.map(x=>({...x,type:"INCOME",desc:x.description||x.source||"Income",credit:Number(x.amount||0),debit:0})),...state.data.expenses.map(x=>({...x,type:"EXPENSE",desc:x.description||x.category||"Expense",credit:0,debit:Number(x.amount||0)})),...state.data.emi.map(x=>({...x,type:"EMI",desc:x.remarks||x.loan||"EMI payment",credit:0,debit:Number(x.amount||0)})),...state.data.ledger.map(x=>{const d=x.direction;const credit=["lena","receive"].includes(d)?Number(x.amount||0):0;const debit=["dena","pay"].includes(d)?Number(x.amount||0):0;return {...x,type:"LEDGER",desc:`${x.person||"Person"} · ${x.directionLabel||d||"Ledger"}`,credit,debit}})].sort((a,b)=>String(a.date||"").localeCompare(String(b.date||"")));let balance=0;const drawTableHead=()=>{doc.setFillColor(...ink);doc.roundedRect(M,y,W-2*M,28,5,5,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(7.5);doc.text("DATE",M+9,y+18);doc.text("TYPE",M+70,y+18);doc.text("DESCRIPTION",M+115,y+18);doc.text("MODE",M+300,y+18);doc.text("CREDIT",M+390,y+18,{align:"right"});doc.text("DEBIT",M+455,y+18,{align:"right"});doc.text("BALANCE",W-M-9,y+18,{align:"right"});y+=28};drawTableHead();rows.forEach((x,idx)=>{if(y>H-75){newPage();y=150;doc.setTextColor(...ink);doc.setFont("helvetica","bold");doc.setFontSize(11);doc.text("TRANSACTION DETAIL · CONTINUED",M,y);y+=14;drawTableHead()}balance+=Number(x.credit||0)-Number(x.debit||0);if(idx%2===0)doc.setFillColor(249,250,252);else doc.setFillColor(255,255,255);doc.rect(M,y,W-2*M,22,"F");doc.setTextColor(...ink);doc.setFont("helvetica","normal");doc.setFontSize(7);doc.text(String(x.date||"").slice(0,10),M+9,y+14);doc.text(short(x.type).slice(0,8),M+70,y+14);doc.text(short(x.desc).slice(0,29),M+115,y+14);doc.text(short(x.mode||"—").slice(0,13),M+300,y+14);if(x.credit)doc.setTextColor(...green);doc.text(x.credit?fmt(x.credit):"—",M+390,y+14,{align:"right"});if(x.debit)doc.setTextColor(...red);doc.text(x.debit?fmt(x.debit):"—",M+455,y+14,{align:"right"});doc.setTextColor(...ink);doc.text(fmt(balance),W-M-9,y+14,{align:"right"});y+=22});if(!rows.length){doc.setTextColor(...muted);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text("No transactions recorded yet.",M+10,y+18);y+=30}y+=18;if(y>H-110){newPage();y=150}doc.setFillColor(...ink);doc.roundedRect(M,y,W-2*M,58,9,9,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("STATEMENT TOTALS",M+14,y+19);doc.setFontSize(8);doc.setFont("helvetica","normal");doc.text(`Income ${fmt(t.income)}   ·   Expenses ${fmt(t.expense)}   ·   EMI ${fmt(t.emi)}`,M+14,y+34);doc.text(`Net Savings ${fmt(t.net)}   ·   To Receive ${fmt(l.receive)}   ·   To Pay ${fmt(l.pay)}`,M+14,y+48);footer();doc.save(`ABS-Statement-${new Date().toISOString().slice(0,10)}.pdf`)}
function resetFinancialData(){openModal("Smart Fresh",`<div class="danger-zone"><div class="workspace-hero"><div class="workspace-icon">🧹</div><div><div class="eyebrow">PROTECTED RESET</div><h3>Clear financial data</h3><p>This permanently clears income, expenses, loans, EMI, people and ledger records for this account.</p></div></div><form id="freshForm"><label class="field"><span>Account Password</span><div class="field-control"><input id="freshPassword" type="password" required placeholder="Enter your account password"></div></label><label class="field"><span>Type RESET to confirm</span><div class="field-control"><input id="freshConfirm" required placeholder="RESET"></div></label><button class="danger full" type="submit">DELETE FINANCIAL DATA</button></form></div>`);$("#freshForm").onsubmit=e=>{e.preventDefault();if($("#freshPassword").value!==localStorage.getItem(`abs_password_${state.user.mobile}`))return toast("Incorrect password");if($("#freshConfirm").value.trim()!=="RESET")return toast("Type RESET to confirm");state.data=EMPTY_DATA();save();closeModal();render();toast("Financial data reset to zero")}}
function logout(){clearSession();state.user=null;setup()}
function openModal(title,body){$("#modalRoot").innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" onclick="closeModal()">×</button></div>${body}</div></div>`}
function closeModal(){$("#modalRoot").innerHTML=""}
window.openAdd=openAdd;window.openCategories=openCategories;window.openHistory=openHistory;window.addCategory=addCategory;window.removeCategory=removeCategory;window.editHistoryEntry=editHistoryEntry;window.exportPDF=exportPDF;window.openFeature=openFeature;window.openEditRecords=openEditRecords;window.closeModal=closeModal;window.renderDashboard=renderDashboard;window.setChartRange=setChartRange;window.openProfileEdit=openProfileEdit;window.openPassword=openPassword;window.toggleTheme=toggleTheme;window.exportData=exportData;window.openAvatarPicker=openAvatarPicker;window.setAvatar=setAvatar;window.logout=logout;window.openPeople=openPeople;window.openPersonForm=openPersonForm;window.openLedger=openLedger;window.openLedgerForm=openLedgerForm;window.processBulkImport=processBulkImport;window.downloadBulkTemplate=downloadBulkTemplate;window.resetFinancialData=resetFinancialData;window.openStatement=openStatement;window.exportStatementPDF=exportStatementPDF;window.requestPremium=requestPremium;window.refreshAppData=refreshAppData;window.goTab=goTab;
